// Static machine-translated drafts; no translation service runs on the published site.
export default Object.freeze({"en":{"copyLanguage":"en","name":"Kinetic Energy Calculator","title":"Kinetic Energy Calculator Free | UsefulVerse","description":"Calculate kinetic and potential energy or solve speed from energy. Free, local and no account.","intro":"Calculate kinetic energy from mass and speed, gravitational potential energy from height, or solve speed from a known kinetic energy. Choose the zero-height reference and gravity used for the estimate.","howQuestion":"How do you calculate kinetic energy?","howAnswer":"Kinetic energy is one half of mass times speed squared: KE = ½mv². Gravitational potential energy relative to a chosen height is PE = mgh. For example, a 2 kg object moving at 3 m/s has 9 J of kinetic energy. The total shown is the sum of these idealized values, not a prediction that includes friction or other losses.","privacyQuestion":"Are my values uploaded?","privacyAnswer":"No. The calculation runs locally in this browser; the values are not uploaded or saved.","fields":{"mode":"Calculation mode","energyMode":"Calculate energy from speed","speedMode":"Solve speed from kinetic energy","massKg":"Mass (kg)","velocityMps":"Speed (m/s)","kineticEnergyJ":"Kinetic energy (J)","heightM":"Height above the zero reference (m)","gravityMps2":"Gravitational acceleration (m/s²)","accuracyNote":"Use height relative to your chosen zero level. Gravity defaults to 9.80665 m/s² but can be changed. This ideal estimate ignores friction, air resistance, rotation and relativistic effects; it is not an engineering or safety assessment."},"actions":{"calculate":"Calculate energy","reset":"Reset","copy":"Copy result","example":"Try 2 kg at 3 m/s","result":"Energy result"},"messages":{"calculated":"Calculation ready.","checkInputs":"Enter a positive mass and valid speed or kinetic energy. Height may be negative; gravity must be greater than zero.","velocity":"Speed","kineticEnergy":"Kinetic energy","potentialEnergy":"Gravitational potential energy","totalEnergy":"Total mechanical energy"},"additionalFaqs":[{"question":"Can I find speed from kinetic energy?","answer":"Yes. Select “Solve speed from kinetic energy,” then enter a positive mass and a kinetic-energy value of zero or greater. The calculator uses v = √(2KE/m)."},{"question":"Why can potential energy be negative?","answer":"Potential energy is measured relative to a reference height that you choose. A position below that zero level has negative mgh; this does not mean the object has negative mass or that kinetic energy is negative."},{"question":"Does total mechanical energy include energy losses?","answer":"No. It is the sum of kinetic and gravitational potential energy only. Friction, air resistance, rotation, deformation and other energy transfers are not modeled."}],"localizationStatus":"approved"},"es":{"copyLanguage":"es","name":"Calculadora de energía cinética","title":"Calculadora de energía cinética | UsefulVerse","description":"Calcula la energía cinética y potencial o resuelve la velocidad a partir de la energía. \nGratis, local y sin cuenta.","intro":"Calcula la energía cinética a partir de la masa y la velocidad, la energía potencial gravitacional a partir de la altura o resuelve la velocidad a partir de una energía cinética conocida. \nElija la referencia de altura cero y la gravedad utilizadas para la estimación.","howQuestion":"¿Cómo se calcula la energía cinética?","howAnswer":"La energía cinética es la mitad de la masa por la velocidad al cuadrado: KE = ½mv². \nLa energía potencial gravitacional relativa a una altura elegida es PE = mgh. \nPor ejemplo, un objeto de 2 kg que se mueve a 3 m/s tiene 9 J de energía cinética. \nEl total mostrado es la suma de estos valores idealizados, no una predicción que incluya fricción u otras pérdidas.","privacyQuestion":"¿Están subidos mis valores?","privacyAnswer":"No. El cálculo se ejecuta localmente en este navegador; \nlos valores no se cargan ni se guardan.","fields":{"mode":"Modo de cálculo","energyMode":"Calcular energía a partir de la velocidad.","speedMode":"Resolver velocidad a partir de energía cinética","massKg":"Masa (kg)","velocityMps":"Velocidad (m/s)","kineticEnergyJ":"Energía cinética (J)","heightM":"Altura sobre la referencia cero (m)","gravityMps2":"Aceleración gravitacional (m/s²)","accuracyNote":"Utilice la altura relativa al nivel cero elegido. \nLa gravedad tiene por defecto 9.80665 m/s², pero se puede cambiar. \nEsta estimación ideal ignora la fricción, la resistencia del aire, la rotación y los efectos relativistas; \nno es una evaluación de ingeniería o seguridad."},"actions":{"calculate":"Calcular energía","reset":"Restablecer","copy":"Copiar resultado","example":"Pruebe 2 kg a 3 m/s","result":"Resultado energético"},"messages":{"calculated":"Cálculo listo.","checkInputs":"Introduzca una masa positiva y una velocidad o energía cinética válida. \nLa altura puede ser negativa; \nla gravedad debe ser mayor que cero.","velocity":"Velocidad","kineticEnergy":"Energía cinética","potentialEnergy":"Energía potencial gravitacional","totalEnergy":"Energía mecánica total"},"additionalFaqs":[{"question":"¿Puedo encontrar la velocidad a partir de la energía cinética?","answer":"Sí. \nSeleccione \"Resolver velocidad a partir de energía cinética\", luego ingrese una masa positiva y un valor de energía cinética de cero o mayor. \nLa calculadora utiliza v = √(2KE/m)."},{"question":"¿Por qué la energía potencial puede ser negativa?","answer":"La energía potencial se mide en relación con una altura de referencia que usted elija. \nUna posición por debajo de ese nivel cero tiene mgh negativo; \nEsto no significa que el objeto tenga masa negativa o que la energía cinética sea negativa."},{"question":"¿La energía mecánica total incluye las pérdidas de energía?","answer":"No. Es únicamente la suma de la energía potencial cinética y gravitacional. \nNo se modelan la fricción, la resistencia del aire, la rotación, la deformación y otras transferencias de energía."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"fr":{"copyLanguage":"fr","name":"Calculateur d'énergie cinétique","title":"Calculateur d'énergie cinétique | UsefulVerse","description":"Calculer l'énergie cinétique et potentielle ou résoudre la vitesse à partir de l'énergie. \nGratuit, local et sans compte.","intro":"Calculez l'énergie cinétique à partir de la masse et de la vitesse, l'énergie potentielle gravitationnelle à partir de la hauteur ou résolvez la vitesse à partir d'une énergie cinétique connue. \nChoisissez la référence de hauteur nulle et la gravité utilisées pour l'estimation.","howQuestion":"Comment calcule-t-on l’énergie cinétique ?","howAnswer":"L'énergie cinétique est égale à la moitié de la masse multipliée par la vitesse au carré : KE = ½mv². \nL'énergie potentielle gravitationnelle par rapport à une hauteur choisie est PE = mgh. \nPar exemple, un objet de 2 kg se déplaçant à 3 m/s possède 9 J d’énergie cinétique. \nLe total indiqué est la somme de ces valeurs idéalisées, et non une prédiction incluant la friction ou d'autres pertes.","privacyQuestion":"Mes valeurs sont-elles téléchargées ?","privacyAnswer":"Non. Le calcul s'exécute localement dans ce navigateur ; \nles valeurs ne sont ni téléchargées ni enregistrées.","fields":{"mode":"Mode de calcul","energyMode":"Calculer l'énergie à partir de la vitesse","speedMode":"Résoudre la vitesse à partir de l'énergie cinétique","massKg":"Masse (kg)","velocityMps":"Vitesse (m/s)","kineticEnergyJ":"Énergie cinétique (J)","heightM":"Hauteur au dessus de la référence zéro (m)","gravityMps2":"Accélération gravitationnelle (m/s²)","accuracyNote":"Utilisez la hauteur par rapport au niveau zéro choisi. \nLa gravité est par défaut 9.80665 m/s² mais peut être modifiée. \nCette estimation idéale ignore le frottement, la résistance de l'air, la rotation et les effets relativistes ; \nil ne s’agit pas d’une évaluation technique ou de sécurité."},"actions":{"calculate":"Calculer l'énergie","reset":"Réinitialiser","copy":"Copier le résultat","example":"Essayez 2 kg à 3 m/s","result":"Résultat énergétique"},"messages":{"calculated":"Calcul prêt.","checkInputs":"Entrez une masse positive et une vitesse ou une énergie cinétique valide. \nLa taille peut être négative ; \nla gravité doit être supérieure à zéro.","velocity":"Vitesse","kineticEnergy":"Énergie cinétique","potentialEnergy":"Énergie potentielle gravitationnelle","totalEnergy":"Énergie mécanique totale"},"additionalFaqs":[{"question":"Puis-je trouver la vitesse à partir de l’énergie cinétique ?","answer":"Oui. \nSélectionnez « Résoudre la vitesse à partir de l’énergie cinétique », puis entrez une masse positive et une valeur d’énergie cinétique égale ou supérieure à zéro. \nLa calculatrice utilise v = √(2KE/m)."},{"question":"Pourquoi l'énergie potentielle peut-elle être négative ?","answer":"L'énergie potentielle est mesurée par rapport à une hauteur de référence que vous choisissez. \nUne position en dessous de ce niveau zéro a un mgh négatif ; \ncela ne signifie pas que l'objet a une masse négative ou que l'énergie cinétique est négative."},{"question":"L'énergie mécanique totale inclut-elle les pertes d'énergie ?","answer":"Non. C'est la somme de l'énergie potentielle cinétique et gravitationnelle uniquement. \nLa friction, la résistance de l’air, la rotation, la déformation et autres transferts d’énergie ne sont pas modélisés."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"pt":{"copyLanguage":"pt","name":"Calculadora de energia cinética","title":"Calculadora de energia cinética | UsefulVerse","description":"Calcule a energia cinética e potencial ou resolva a velocidade a partir da energia. \nGratuito, local e sem conta.","intro":"Calcule a energia cinética a partir da massa e da velocidade, a energia potencial gravitacional a partir da altura ou resolva a velocidade a partir de uma energia cinética conhecida. \nEscolha a referência de altura zero e a gravidade usadas para a estimativa.","howQuestion":"Como você calcula a energia cinética?","howAnswer":"A energia cinética é metade da massa vezes a velocidade ao quadrado: KE = ½mv². \nA energia potencial gravitacional relativa a uma altura escolhida é PE = mgh. \nPor exemplo, um objeto de 2 kg movendo-se a 3 m/s possui 9 J de energia cinética. \nO total mostrado é a soma desses valores idealizados, e não uma previsão que inclua atrito ou outras perdas.","privacyQuestion":"Meus valores foram carregados?","privacyAnswer":"Não. O cálculo é executado localmente neste navegador; \nos valores não são carregados ou salvos.","fields":{"mode":"Modo de cálculo","energyMode":"Calcular energia a partir da velocidade","speedMode":"Resolva a velocidade a partir da energia cinética","massKg":"Massa (kg)","velocityMps":"Velocidade (m/s)","kineticEnergyJ":"Energia cinética (J)","heightM":"Altura acima da referência zero (m)","gravityMps2":"Aceleração gravitacional (m/s²)","accuracyNote":"Use a altura relativa ao nível zero escolhido. \nO padrão da gravidade é 9.80665 m/s², mas pode ser alterado. \nEsta estimativa ideal ignora o atrito, a resistência do ar, a rotação e os efeitos relativísticos; \nnão é uma avaliação de engenharia ou segurança."},"actions":{"calculate":"Calcular energia","reset":"Redefinir","copy":"Copiar resultado","example":"Experimente 2 kg a 3 m/s","result":"Resultado energético"},"messages":{"calculated":"Cálculo pronto.","checkInputs":"Insira uma massa positiva e uma velocidade ou energia cinética válida. \nA altura pode ser negativa; \na gravidade deve ser maior que zero.","velocity":"Velocidade","kineticEnergy":"Energia cinética","potentialEnergy":"Energia potencial gravitacional","totalEnergy":"Energia mecânica total"},"additionalFaqs":[{"question":"Posso encontrar a velocidade a partir da energia cinética?","answer":"Sim. \nSelecione “Resolver a velocidade a partir da energia cinética” e insira uma massa positiva e um valor de energia cinética igual a zero ou superior. \nA calculadora usa v = √(2KE/m)."},{"question":"Por que a energia potencial pode ser negativa?","answer":"A energia potencial é medida em relação a uma altura de referência escolhida. \nUma posição abaixo desse nível zero tem mgh negativo; \nisso não significa que o objeto tenha massa negativa ou que a energia cinética seja negativa."},{"question":"A energia mecânica total inclui perdas de energia?","answer":"Não. É apenas a soma da energia potencial cinética e gravitacional. \nFricção, resistência do ar, rotação, deformação e outras transferências de energia não são modeladas."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"de":{"copyLanguage":"de","name":"Rechner für kinetische Energie","title":"Rechner für kinetische Energie | UsefulVerse","description":"Berechnen Sie kinetische und potentielle Energie oder lösen Sie Geschwindigkeit aus Energie. \nKostenlos, lokal und ohne Konto.","intro":"Berechnen Sie die kinetische Energie aus Masse und Geschwindigkeit, die potentielle Gravitationsenergie aus der Höhe oder ermitteln Sie die Geschwindigkeit anhand einer bekannten kinetischen Energie. \nWählen Sie die Nullhöhenreferenz und die Schwerkraft, die für die Schätzung verwendet werden.","howQuestion":"Wie berechnet man die kinetische Energie?","howAnswer":"Die kinetische Energie ist die Hälfte der Masse mal der Geschwindigkeit im Quadrat: KE = ½mv². \nDie potenzielle Gravitationsenergie relativ zu einer gewählten Höhe beträgt PE = mgh. \nBeispielsweise hat ein 2 kg schweres Objekt, das sich mit 3 m/s bewegt, eine kinetische Energie von 9 J. \nDer angezeigte Gesamtwert ist die Summe dieser idealisierten Werte und keine Vorhersage, die Reibung oder andere Verluste berücksichtigt.","privacyQuestion":"Werden meine Werte hochgeladen?","privacyAnswer":"Nein. Die Berechnung läuft lokal in diesem Browser; \nDie Werte werden nicht hochgeladen oder gespeichert.","fields":{"mode":"Berechnungsmodus","energyMode":"Energie aus Geschwindigkeit berechnen","speedMode":"Lösen Sie Geschwindigkeit aus kinetischer Energie","massKg":"Masse (kg)","velocityMps":"Geschwindigkeit (m/s)","kineticEnergyJ":"Kinetische Energie (J)","heightM":"Höhe über der Nullreferenz (m)","gravityMps2":"Erdbeschleunigung (m/s²)","accuracyNote":"Verwenden Sie die Höhe relativ zur von Ihnen gewählten Nullebene. \nDie Schwerkraft ist standardmäßig auf 9.80665 m/s² eingestellt, kann aber geändert werden. \nDiese ideale Schätzung ignoriert Reibung, Luftwiderstand, Rotation und relativistische Effekte; \nEs handelt sich nicht um eine technische oder sicherheitstechnische Bewertung."},"actions":{"calculate":"Energie berechnen","reset":"Zurücksetzen","copy":"Ergebnis kopieren","example":"Versuchen Sie es mit 2 kg bei 3 m/s","result":"Energieergebnis"},"messages":{"calculated":"Berechnung bereit.","checkInputs":"Geben Sie eine positive Masse und eine gültige Geschwindigkeit oder kinetische Energie ein. \nDie Höhe kann negativ sein; \nDie Schwerkraft muss größer als Null sein.","velocity":"Geschwindigkeit","kineticEnergy":"Kinetische Energie","potentialEnergy":"Gravitationspotentialenergie","totalEnergy":"Gesamte mechanische Energie"},"additionalFaqs":[{"question":"Kann ich Geschwindigkeit aus kinetischer Energie ermitteln?","answer":"Ja. \nWählen Sie „Geschwindigkeit anhand der kinetischen Energie berechnen“ aus und geben Sie dann eine positive Masse und einen kinetischen Energiewert von Null oder größer ein. \nDer Rechner verwendet v = √(2KE/m)."},{"question":"Warum kann potentielle Energie negativ sein?","answer":"Die potenzielle Energie wird relativ zu einer von Ihnen gewählten Referenzhöhe gemessen. \nEine Position unterhalb dieses Nullniveaus weist negative mgh auf; \nDies bedeutet nicht, dass das Objekt eine negative Masse hat oder dass die kinetische Energie negativ ist."},{"question":"Beinhaltet die gesamte mechanische Energie Energieverluste?","answer":"Nein. Es ist nur die Summe aus kinetischer und gravitativer potentieller Energie. \nReibung, Luftwiderstand, Rotation, Verformung und andere Energieübertragungen werden nicht modelliert."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ja":{"copyLanguage":"ja","name":"運動エネルギー計算機","title":"運動エネルギー計算機 | UsefulVerse","description":"運動エネルギーと位置エネルギーを計算したり、エネルギーから速度を解きます。\n無料、ローカル、アカウントなし。","intro":"質量と速度から運動エネルギーを計算したり、高さから重力位置エネルギーを計算したり、既知の運動エネルギーから速度を解きます。\n推定に使用されるゼロ高さの基準と重力を選択します。","howQuestion":"運動エネルギーはどのように計算しますか?","howAnswer":"運動エネルギーは、質量と速度の 2 乗の 2 分の 1 です: KE = ½mv²。\n選択した高さに対する重力位置エネルギーは PE = mgh です。\nたとえば、3 m/s で移動する 2 kg の物体の運動エネルギーは 9 J です。\n表示される合計は、これらの理想化された値の合計であり、摩擦やその他の損失を含む予測ではありません。","privacyQuestion":"私の値はアップロードされていますか?","privacyAnswer":"いいえ。計算はこのブラウザでローカルに実行されます。\n値はアップロードまたは保存されません。","fields":{"mode":"計算モード","energyMode":"速度からエネルギーを計算する","speedMode":"運動エネルギーから速度を求める","massKg":"質量(kg)","velocityMps":"速度 (m/s)","kineticEnergyJ":"運動エネルギー (J)","heightM":"ゼロ基準より上の高さ (m)","gravityMps2":"重力加速度 (m/s²)","accuracyNote":"選択したゼロ レベルを基準とした高さを使用します。\n重力のデフォルトは 9.80665 m/s² ですが、変更できます。\nこの理想的な推定では、摩擦、空気抵抗、回転、相対論的効果は無視されています。\nこれは工学的または安全性の評価ではありません。"},"actions":{"calculate":"エネルギーを計算する","reset":"リセット","copy":"コピー結果","example":"3 m/s で 2 kg を試してください","result":"エネルギー結果"},"messages":{"calculated":"計算の準備ができました。","checkInputs":"正の質量と有効な速度または運動エネルギーを入力してください。\n高さは負の値になる場合があります。\n重力はゼロより大きくなければなりません。","velocity":"速度","kineticEnergy":"運動エネルギー","potentialEnergy":"重力位置エネルギー","totalEnergy":"総機械エネルギー"},"additionalFaqs":[{"question":"運動エネルギーから速度を求めることはできますか?","answer":"はい。 \n「運動エネルギーから速度を計算する」を選択し、正の質量とゼロ以上の運動エネルギー値を入力します。\n電卓はv = √(2KE/m)を使用しています。"},{"question":"位置エネルギーが負になるのはなぜですか?","answer":"位置エネルギーは、選択した基準高さを基準にして測定されます。\nそのゼロレベルを下回るポジションはマイナスの mgh を持ちます。\nこれは、物体の質量が負であることや、運動エネルギーが負であることを意味するものではありません。"},{"question":"総機械エネルギーにはエネルギー損失が含まれますか?","answer":"いいえ。これは運動エネルギーと重力位置エネルギーのみの合計です。\n摩擦、空気抵抗、回転、変形、その他のエネルギー伝達はモデル化されません。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ko":{"copyLanguage":"ko","name":"운동 에너지 계산기","title":"운동 에너지 계산기 | UsefulVerse","description":"운동 에너지와 위치 에너지를 계산하거나 에너지로부터 속도를 구합니다. \n무료, 로컬 및 계정이 없습니다.","intro":"질량과 속도로부터 운동 에너지를 계산하고, 높이로부터 중력 위치 에너지를 계산하거나 알려진 운동 에너지로부터 속도를 계산합니다. \n추정에 사용되는 제로 높이 기준과 중력을 선택합니다.","howQuestion":"운동에너지는 어떻게 계산하나요?","howAnswer":"운동 에너지는 질량 곱하기 속도의 제곱의 절반인 KE = ½mv²입니다. \n선택한 높이에 대한 중력 위치 에너지는 PE = mgh입니다. \n예를 들어, 3m/s의 속도로 움직이는 2kg의 물체의 운동 에너지는 9J입니다. \n표시된 총계는 마찰이나 기타 손실을 포함하는 예측이 아니라 이상화된 값의 합계입니다.","privacyQuestion":"내 값이 업로드됩니까?","privacyAnswer":"아니요. 계산은 이 브라우저에서 로컬로 실행됩니다. \n값은 업로드되거나 저장되지 않습니다.","fields":{"mode":"계산 모드","energyMode":"속도로부터 에너지를 계산","speedMode":"운동에너지로부터 속도를 푼다","massKg":"질량(kg)","velocityMps":"속도(m/s)","kineticEnergyJ":"운동에너지(J)","heightM":"제로 기준 위 높이(m)","gravityMps2":"중력 가속도(m/s²)","accuracyNote":"선택한 0 레벨을 기준으로 높이를 사용합니다. \n중력의 기본값은 9.80665 m/s²이지만 변경할 수 있습니다. \n이 이상적인 추정치는 마찰, 공기 저항, 회전 및 상대론적 효과를 무시합니다. \n이는 공학적 평가나 안전성 평가가 아닙니다."},"actions":{"calculate":"에너지 계산","reset":"재설정","copy":"결과 복사","example":"3m/s에서 2kg을 시도해 보세요.","result":"에너지 결과"},"messages":{"calculated":"계산이 준비되었습니다.","checkInputs":"양의 질량과 유효한 속도 또는 운동 에너지를 입력하세요. \n높이는 음수일 수 있습니다. \n중력은 0보다 커야 합니다.","velocity":"속도","kineticEnergy":"운동에너지","potentialEnergy":"중력 위치에너지","totalEnergy":"총 기계적 에너지"},"additionalFaqs":[{"question":"운동에너지로 속도를 구할 수 있나요?","answer":"네. \n\"운동 에너지에서 속도 계산\"을 선택한 다음 양의 질량과 0 이상의 운동 에너지 값을 입력합니다. \n계산기는 v = √(2KE/m)를 사용합니다."},{"question":"왜 위치에너지가 음수가 될 수 있나요?","answer":"위치 에너지는 선택한 기준 높이를 기준으로 측정됩니다. \n0 수준 아래의 위치는 음의 mgh를 갖습니다. \n이는 물체의 질량이 음수이거나 운동 에너지가 음수라는 의미는 아닙니다."},{"question":"총 기계적 에너지에 에너지 손실이 포함됩니까?","answer":"아니요. 운동에너지와 중력 위치에너지의 합입니다. \n마찰, 공기 저항, 회전, 변형 및 기타 에너지 전달은 모델링되지 않습니다."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"id":{"copyLanguage":"id","name":"Kalkulator Energi Kinetik","title":"Kalkulator Energi Kinetik | UsefulVerse","description":"Hitung energi kinetik dan potensial atau selesaikan kecepatan dari energi. \nGratis, lokal dan tanpa akun.","intro":"Hitung energi kinetik dari massa dan kecepatan, energi potensial gravitasi dari ketinggian, atau selesaikan kecepatan dari energi kinetik yang diketahui. \nPilih referensi ketinggian nol dan gravitasi yang digunakan untuk perkiraan.","howQuestion":"Bagaimana cara menghitung energi kinetik?","howAnswer":"Energi kinetik adalah setengah massa dikalikan kecepatan kuadrat: KE = ½mv². \nEnergi potensial gravitasi relatif terhadap ketinggian yang dipilih adalah PE = mgh. \nMisalnya, sebuah benda bermassa 2 kg yang bergerak dengan kecepatan 3 m/s mempunyai energi kinetik 9 J. \nTotal yang ditampilkan adalah jumlah dari nilai ideal tersebut, bukan prediksi yang mencakup gesekan atau kerugian lainnya.","privacyQuestion":"Apakah nilai saya sudah diunggah?","privacyAnswer":"Tidak. Perhitungan berjalan secara lokal di browser ini; \nnilainya tidak diunggah atau disimpan.","fields":{"mode":"Mode perhitungan","energyMode":"Hitung energi dari kecepatan","speedMode":"Selesaikan kecepatan dari energi kinetik","massKg":"Massa (kg)","velocityMps":"Kecepatan (m/s)","kineticEnergyJ":"Energi kinetik (J)","heightM":"Ketinggian di atas acuan nol (m)","gravityMps2":"Percepatan gravitasi (m/s²)","accuracyNote":"Gunakan ketinggian relatif terhadap level nol yang Anda pilih. \nGravitasi defaultnya adalah 9.80665 m/s² tetapi dapat diubah. \nPerkiraan ideal ini mengabaikan gesekan, hambatan udara, rotasi, dan efek relativistik; \nini bukan penilaian teknik atau keselamatan."},"actions":{"calculate":"Hitung energi","reset":"Atur Ulang","copy":"Salin hasil","example":"Coba 2 kg dengan kecepatan 3 m/s","result":"Hasil energi"},"messages":{"calculated":"Perhitungan siap.","checkInputs":"Masukkan massa positif dan kecepatan valid atau energi kinetik. \nTinggi badan mungkin negatif; \ngravitasi harus lebih besar dari nol.","velocity":"Kecepatan","kineticEnergy":"Energi kinetik","potentialEnergy":"Energi potensial gravitasi","totalEnergy":"Total energi mekanik"},"additionalFaqs":[{"question":"Dapatkah saya mencari kecepatan dari energi kinetik?","answer":"Ya. \nPilih “Selesaikan kecepatan dari energi kinetik”, lalu masukkan massa positif dan nilai energi kinetik nol atau lebih besar. \nKalkulator menggunakan v = √(2KE/m)."},{"question":"Mengapa energi potensial bisa negatif?","answer":"Energi potensial diukur relatif terhadap ketinggian referensi yang Anda pilih. \nPosisi di bawah level nol tersebut memiliki mgh negatif; \nini tidak berarti benda tersebut mempunyai massa negatif atau energi kinetiknya negatif."},{"question":"Apakah energi mekanik total sudah termasuk energi yang hilang?","answer":"Tidak. Ini adalah jumlah energi potensial kinetik dan gravitasi saja. \nGesekan, hambatan udara, rotasi, deformasi, dan perpindahan energi lainnya tidak dimodelkan."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"hi":{"copyLanguage":"hi","name":"गतिज ऊर्जा कैलकुलेटर","title":"गतिज ऊर्जा कैलकुलेटर | UsefulVerse","description":"गतिज और स्थितिज ऊर्जा की गणना करें या ऊर्जा से गति का समाधान करें। \nमुफ़्त, स्थानीय और कोई खाता नहीं।","intro":"द्रव्यमान और गति से गतिज ऊर्जा, ऊंचाई से गुरुत्वाकर्षण संभावित ऊर्जा की गणना करें, या किसी ज्ञात गतिज ऊर्जा से गति को हल करें। \nअनुमान के लिए प्रयुक्त शून्य-ऊंचाई संदर्भ और गुरुत्वाकर्षण चुनें।","howQuestion":"आप गतिज ऊर्जा की गणना कैसे करते हैं?","howAnswer":"गतिज ऊर्जा द्रव्यमान गुना गति वर्ग का आधा है: KE = ½mv²। \nचुनी गई ऊंचाई के सापेक्ष गुरुत्वाकर्षण संभावित ऊर्जा PE = mgh है। \nउदाहरण के लिए, 3 मी/सेकेंड की गति से चलने वाली 2 किलो की वस्तु में 9 J गतिज ऊर्जा होती है। \nदिखाया गया कुल इन आदर्श मूल्यों का योग है, न कि कोई भविष्यवाणी जिसमें घर्षण या अन्य नुकसान शामिल हैं।","privacyQuestion":"क्या मेरे मान अपलोड किए गए हैं?","privacyAnswer":"नहीं। गणना इस ब्राउज़र में स्थानीय रूप से चलती है; \nमान अपलोड या सहेजे नहीं गए हैं.","fields":{"mode":"गणना मोड","energyMode":"गति से ऊर्जा की गणना करें","speedMode":"गति को गतिज ऊर्जा से हल करें","massKg":"द्रव्यमान (किग्रा)","velocityMps":"गति (एम/एस)","kineticEnergyJ":"गतिज ऊर्जा (जे)","heightM":"शून्य संदर्भ से ऊपर ऊंचाई (एम)","gravityMps2":"गुरुत्वाकर्षण त्वरण (एम/एस²)","accuracyNote":"अपने चुने हुए शून्य स्तर के सापेक्ष ऊंचाई का उपयोग करें। \nग्रेविटी डिफ़ॉल्ट रूप से 9.80665 m/s² है लेकिन इसे बदला जा सकता है। \nयह आदर्श अनुमान घर्षण, वायु प्रतिरोध, घूर्णन और सापेक्ष प्रभावों को नजरअंदाज करता है; \nयह कोई इंजीनियरिंग या सुरक्षा मूल्यांकन नहीं है।"},"actions":{"calculate":"ऊर्जा की गणना करें","reset":"रीसेट करें","copy":"परिणाम कॉपी करें","example":"3 मी./सेकेंड पर 2 किलो वजन उठाने का प्रयास करें","result":"ऊर्जा परिणाम"},"messages":{"calculated":"गणना तैयार।","checkInputs":"एक सकारात्मक द्रव्यमान और वैध गति या गतिज ऊर्जा दर्ज करें। \nऊंचाई नकारात्मक हो सकती है; \nगुरुत्वाकर्षण शून्य से अधिक होना चाहिए.","velocity":"स्पीड","kineticEnergy":"गतिज ऊर्जा","potentialEnergy":"गुरुत्वीय स्थितिज ऊर्जा","totalEnergy":"कुल यांत्रिक ऊर्जा"},"additionalFaqs":[{"question":"क्या मैं गतिज ऊर्जा से गति ज्ञात कर सकता हूँ?","answer":"हाँ। \n\"गतिज ऊर्जा से गति का समाधान करें\" चुनें, फिर एक सकारात्मक द्रव्यमान और शून्य या अधिक का गतिज-ऊर्जा मान दर्ज करें। \nकैलकुलेटर v = √(2KE/m) का उपयोग करता है।"},{"question":"स्थितिज ऊर्जा ऋणात्मक क्यों हो सकती है?","answer":"संभावित ऊर्जा को आपके द्वारा चुनी गई संदर्भ ऊंचाई के सापेक्ष मापा जाता है। \nउस शून्य स्तर से नीचे की स्थिति में नकारात्मक mgh है; \nइसका मतलब यह नहीं है कि वस्तु का द्रव्यमान ऋणात्मक है या गतिज ऊर्जा ऋणात्मक है।"},{"question":"क्या कुल यांत्रिक ऊर्जा में ऊर्जा हानि शामिल है?","answer":"नहीं, यह केवल गतिज और गुरुत्वाकर्षण स्थितिज ऊर्जा का योग है। \nघर्षण, वायु प्रतिरोध, घूर्णन, विरूपण और अन्य ऊर्जा हस्तांतरण को मॉडल नहीं किया गया है।"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ar":{"copyLanguage":"ar","name":"حاسبة الطاقة الحركية","title":"حاسبة الطاقة الحركية | UsefulVerse","description":"حساب الطاقة الحركية والطاقة الكامنة أو حل السرعة من الطاقة. \nمجاني ومحلي وبدون حساب.","intro":"حساب الطاقة الحركية من الكتلة والسرعة، طاقة الجاذبية الكامنة من الارتفاع، أو حل السرعة من طاقة حركية معروفة. \nاختر مرجع الارتفاع الصفري والجاذبية المستخدمة في التقدير.","howQuestion":"كيف تحسب الطاقة الحركية؟","howAnswer":"الطاقة الحركية هي نصف الكتلة مضروبة في مربع السرعة: KE = ½mv². \nطاقة الجاذبية الكامنة بالنسبة للارتفاع المختار هي PE = mgh. \nعلى سبيل المثال، جسم كتلته 2 كجم يتحرك بسرعة 3 م/ث لديه 9 J من الطاقة الحركية. \nالإجمالي الموضح هو مجموع هذه القيم المثالية، وليس توقعًا يتضمن احتكاكًا أو خسائر أخرى.","privacyQuestion":"هل تم تحميل القيم الخاصة بي؟","privacyAnswer":"لا. يتم تشغيل الحساب محليًا في هذا المتصفح؛ \nلا يتم تحميل القيم أو حفظها.","fields":{"mode":"وضع الحساب","energyMode":"حساب الطاقة من السرعة","speedMode":"حل السرعة من الطاقة الحركية","massKg":"الكتلة (كجم)","velocityMps":"السرعة (م/ث)","kineticEnergyJ":"الطاقة الحركية (ي)","heightM":"الارتفاع فوق مرجع الصفر (م)","gravityMps2":"تسارع الجاذبية (م/ث²)","accuracyNote":"استخدم الارتفاع بالنسبة لمستوى الصفر الذي اخترته. \nافتراضيات الجاذبية هي 9.80665 m/s² ولكن يمكن تغييرها. \nيتجاهل هذا التقدير المثالي الاحتكاك ومقاومة الهواء والدوران والتأثيرات النسبية؛ \nإنه ليس تقييمًا هندسيًا أو للسلامة."},"actions":{"calculate":"حساب الطاقة","reset":"إعادة تعيين","copy":"نسخ النتيجة","example":"جرب 2 كجم بسرعة 3 م/ث","result":"نتيجة الطاقة"},"messages":{"calculated":"الحساب جاهز.","checkInputs":"أدخل كتلة موجبة وسرعة صالحة أو طاقة حركية. \nقد يكون الارتفاع سلبيا. \nيجب أن تكون الجاذبية أكبر من الصفر.","velocity":"السرعة","kineticEnergy":"الطاقة الحركية","potentialEnergy":"طاقة الجاذبية الكامنة","totalEnergy":"إجمالي الطاقة الميكانيكية"},"additionalFaqs":[{"question":"هل يمكنني إيجاد السرعة من الطاقة الحركية؟","answer":"نعم. \nحدد \"حل السرعة من الطاقة الحركية\"، ثم أدخل كتلة موجبة وقيمة طاقة حركية تساوي صفرًا أو أكبر. \nالآلة الحاسبة تستخدم v = √(2KE/m)."},{"question":"لماذا يمكن أن تكون الطاقة الكامنة سلبية؟","answer":"يتم قياس الطاقة الكامنة بالنسبة للارتفاع المرجعي الذي تختاره. \nالمركز تحت مستوى الصفر هذا له قيمة سلبية؛ \nهذا لا يعني أن الجسم له كتلة سالبة أو أن الطاقة الحركية سالبة."},{"question":"هل يشمل إجمالي الطاقة الميكانيكية فاقد الطاقة؟","answer":"لا. إنها مجموع طاقة الوضع الحركية والجاذبية فقط. \nلم يتم وضع نموذج للاحتكاك ومقاومة الهواء والدوران والتشوه وعمليات نقل الطاقة الأخرى."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"zh":{"copyLanguage":"zh","name":"动能计算器","title":"动能计算器 | UsefulVerse","description":"计算动能和势能或根据能量求解速度。\n免费、本地且无需帐户。","intro":"根据质量和速度计算动能，根据高度计算重力势能，或根据已知动能求解速度。\n选择用于估计的零高度参考和重力。","howQuestion":"如何计算动能？","howAnswer":"动能是质量乘以速度平方的一半：KE = ½mv²。\n相对于选定高度的重力势能是 PE = mgh。\n例如，以 3 m/s 速度运动的 2 kg 物体具有 9 J 的动能。\n显示的总数是这些理想值的总和，而不是包含摩擦或其他损失的预测。","privacyQuestion":"我的值上传了吗？","privacyAnswer":"否。计算在此浏览器中本地运行；\n这些值不会上传或保存。","fields":{"mode":"计算模式","energyMode":"根据速度计算能量","speedMode":"从动能求解速度","massKg":"质量（公斤）","velocityMps":"速度（米/秒）","kineticEnergyJ":"动能 (J)","heightM":"零参考上方的高度 (m)","gravityMps2":"重力加速度 (m/s²)","accuracyNote":"使用相对于您选择的零水平的高度。\n重力默认为 9.80665 m/s²，但可以更改。\n这种理想的估计忽略了摩擦、空气阻力、旋转和相对论效应；\n它不是工程或安全评估。"},"actions":{"calculate":"计算能量","reset":"重置","copy":"复制结果","example":"尝试以 3 m/s 的速度加载 2 kg","result":"能量结果"},"messages":{"calculated":"计算就绪。","checkInputs":"输入正质量和有效速度或动能。\n高度可以为负值；\n重力必须大于零。","velocity":"速度","kineticEnergy":"动能","potentialEnergy":"重力势能","totalEnergy":"总机械能"},"additionalFaqs":[{"question":"我能从动能中求出速度吗？","answer":"是的。\n选择“根据动能求解速度”，然后输入正质量和零或更大的动能值。\n计算器使用v = √(2KE/m)。"},{"question":"为什么势能可以为负值？","answer":"势能是相对于您选择的参考高度进行测量的。\n低于该零水平的位置具有负 mgh；\n这并不意味着该物体具有负质量或动能为负。"},{"question":"总机械能包括能量损失吗？","answer":"否。它只是动能和重力势能的总和。\n摩擦、空气阻力、旋转、变形和其他能量传递没有建模。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"bn":{"copyLanguage":"bn","name":"গতিশক্তি ক্যালকুলেটর","title":"গতিশক্তি ক্যালকুলেটর | UsefulVerse","description":"গতি এবং সম্ভাব্য শক্তি গণনা করুন বা শক্তি থেকে গতি সমাধান করুন। \nবিনামূল্যে, স্থানীয় এবং কোনো অ্যাকাউন্ট নেই।","intro":"ভর এবং গতি থেকে গতিশক্তি গণনা করুন, উচ্চতা থেকে মহাকর্ষীয় সম্ভাব্য শক্তি, অথবা পরিচিত গতিশক্তি থেকে গতির সমাধান করুন। \nঅনুমানের জন্য ব্যবহৃত শূন্য-উচ্চতার রেফারেন্স এবং মাধ্যাকর্ষণ চয়ন করুন।","howQuestion":"আপনি কিভাবে গতিশক্তি গণনা করবেন?","howAnswer":"গতিশক্তি হল ভর গুন গতির বর্গক্ষেত্রের এক অর্ধেক: KE = ½mv²। \nএকটি নির্বাচিত উচ্চতার সাপেক্ষে মহাকর্ষীয় সম্ভাব্য শক্তি হল PE = mgh। \nউদাহরণস্বরূপ, একটি 2 কেজি বস্তু 3 মি/সেকেন্ড গতিতে চলে তার 9 জে গতিশক্তি থাকে। \nদেখানো মোট এই আদর্শ মানগুলির সমষ্টি, কোনো ভবিষ্যদ্বাণী নয় যাতে ঘর্ষণ বা অন্যান্য ক্ষতি অন্তর্ভুক্ত থাকে।","privacyQuestion":"আমার মান কি আপলোড করা হয়েছে?","privacyAnswer":"নং। গণনা এই ব্রাউজারে স্থানীয়ভাবে চলে; \nমান আপলোড বা সংরক্ষণ করা হয় না.","fields":{"mode":"গণনা মোড","energyMode":"গতি থেকে শক্তি গণনা করুন","speedMode":"গতিশক্তি থেকে গতি সমাধান করুন","massKg":"ভর (কেজি)","velocityMps":"গতি (m/s)","kineticEnergyJ":"গতিশক্তি (J)","heightM":"শূন্য রেফারেন্সের উপরে উচ্চতা (মি)","gravityMps2":"মহাকর্ষীয় ত্বরণ (m/s²)","accuracyNote":"আপনার নির্বাচিত শূন্য স্তরের তুলনায় উচ্চতা ব্যবহার করুন। \nমাধ্যাকর্ষণ ডিফল্ট 9.80665 m/s² কিন্তু পরিবর্তন করা যেতে পারে। \nএই আদর্শ অনুমান ঘর্ষণ, বায়ু প্রতিরোধ, ঘূর্ণন এবং আপেক্ষিক প্রভাব উপেক্ষা করে; \nএটি একটি প্রকৌশল বা নিরাপত্তা মূল্যায়ন নয়।"},"actions":{"calculate":"শক্তি গণনা করুন","reset":"রিসেট করুন","copy":"ফলাফল কপি করুন","example":"3 মি/সেকেন্ডে 2 কেজি চেষ্টা করুন","result":"শক্তি ফলাফল"},"messages":{"calculated":"গণনা প্রস্তুত।","checkInputs":"একটি ধনাত্মক ভর এবং বৈধ গতি বা গতিশক্তি লিখুন। \nউচ্চতা নেতিবাচক হতে পারে; \nমাধ্যাকর্ষণ অবশ্যই শূন্যের চেয়ে বেশি হতে হবে।","velocity":"গতি","kineticEnergy":"গতিশক্তি","potentialEnergy":"মহাকর্ষীয় সম্ভাব্য শক্তি","totalEnergy":"মোট যান্ত্রিক শক্তি"},"additionalFaqs":[{"question":"আমি কি গতিশক্তি থেকে গতি খুঁজে পেতে পারি?","answer":"হ্যাঁ। \n\"গতিশক্তি থেকে গতি সমাধান করুন\" নির্বাচন করুন, তারপর একটি ধনাত্মক ভর এবং শূন্য বা তার বেশি একটি গতি-শক্তি মান লিখুন। \nক্যালকুলেটর v = √(2KE/m) ব্যবহার করে।"},{"question":"কেন সম্ভাব্য শক্তি ঋণাত্মক হতে পারে?","answer":"সম্ভাব্য শক্তি আপনার বেছে নেওয়া একটি রেফারেন্স উচ্চতার সাপেক্ষে পরিমাপ করা হয়। \nশূন্য স্তরের নিচের অবস্থানে ঋণাত্মক mgh আছে; \nএর মানে এই নয় যে বস্তুটির নেতিবাচক ভর আছে বা গতিশক্তি ঋণাত্মক।"},{"question":"মোট যান্ত্রিক শক্তি কি শক্তির ক্ষতি অন্তর্ভুক্ত করে?","answer":"নং। এটি শুধুমাত্র গতি এবং মহাকর্ষীয় সম্ভাব্য শক্তির সমষ্টি। \nঘর্ষণ, বায়ু প্রতিরোধ, ঘূর্ণন, বিকৃতি এবং অন্যান্য শক্তি স্থানান্তর মডেল করা হয় না।"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ru":{"copyLanguage":"ru","name":"Калькулятор кинетической энергии","title":"Калькулятор кинетической энергии | UsefulVerse","description":"Рассчитайте кинетическую и потенциальную энергию или определите скорость по энергии. \nБесплатно, локально и без учетной записи.","intro":"Рассчитайте кинетическую энергию по массе и скорости, потенциальную энергию гравитации по высоте или определите скорость по известной кинетической энергии. \nВыберите привязку нулевой высоты и силу тяжести, используемые для оценки.","howQuestion":"Как рассчитать кинетическую энергию?","howAnswer":"Кинетическая энергия равна половине массы, умноженной на квадрат скорости: KE = ½mv². \nГравитационная потенциальная энергия относительно выбранной высоты равна PE = mgh. \nНапример, объект массой 2 кг, движущийся со скоростью 3 м/с, имеет кинетическую энергию 9 Дж. \nПоказанная общая сумма представляет собой сумму этих идеализированных значений, а не прогноз, включающий трение или другие потери.","privacyQuestion":"Мои значения загружены?","privacyAnswer":"Нет. Расчет выполняется локально в этом браузере; \nзначения не загружаются и не сохраняются.","fields":{"mode":"Режим расчета","energyMode":"Вычисляем энергию по скорости.","speedMode":"Определить скорость по кинетической энергии.","massKg":"Масса (кг)","velocityMps":"Скорость (м/с)","kineticEnergyJ":"Кинетическая энергия (Дж)","heightM":"Высота над нулевой отметкой (м)","gravityMps2":"Гравитационное ускорение (м/с²)","accuracyNote":"Используйте высоту относительно выбранного вами нулевого уровня. \nПо умолчанию для гравитации установлено значение 9.80665 m/s², но его можно изменить. \nЭта идеальная оценка игнорирует трение, сопротивление воздуха, вращение и релятивистские эффекты; \nэто не инженерная оценка или оценка безопасности."},"actions":{"calculate":"Рассчитать энергию","reset":"Сброс","copy":"Копировать результат","example":"Попробуйте 2 кг на скорости 3 м/с.","result":"Энергетический результат"},"messages":{"calculated":"Расчет готов.","checkInputs":"Введите положительную массу и допустимую скорость или кинетическую энергию. \nВысота может быть отрицательной; \nсила тяжести должна быть больше нуля.","velocity":"Скорость","kineticEnergy":"Кинетическая энергия","potentialEnergy":"Гравитационная потенциальная энергия","totalEnergy":"Полная механическая энергия"},"additionalFaqs":[{"question":"Можно ли найти скорость по кинетической энергии?","answer":"Да. \nВыберите «Определить скорость по кинетической энергии», затем введите положительную массу и значение кинетической энергии, равное нулю или больше. \nКалькулятор использует v = √(2KE/m)."},{"question":"Почему потенциальная энергия может быть отрицательной?","answer":"Потенциальная энергия измеряется относительно выбранной вами базовой высоты. \nПозиция ниже нулевого уровня имеет отрицательный mgh; \nэто не означает, что объект имеет отрицательную массу или что кинетическая энергия отрицательна."},{"question":"Включает ли общая механическая энергия потери энергии?","answer":"Нет. Это только сумма кинетической и гравитационной потенциальной энергии. \nТрение, сопротивление воздуха, вращение, деформация и другие виды передачи энергии не моделируются."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ur":{"copyLanguage":"ur","name":"کائنےٹک انرجی کیلکولیٹر","title":"کائنےٹک انرجی کیلکولیٹر | UsefulVerse","description":"حرکی اور ممکنہ توانائی کا حساب لگائیں یا توانائی سے رفتار حل کریں۔ \nمفت، مقامی اور کوئی اکاؤنٹ نہیں۔","intro":"کمیت اور رفتار سے حرکی توانائی کا حساب لگائیں، اونچائی سے ثقلی امکانی توانائی، یا معلوم حرکی توانائی سے رفتار حل کریں۔ \nتخمینہ کے لیے زیرو اونچائی کا حوالہ اور کشش ثقل کا انتخاب کریں۔","howQuestion":"آپ حرکی توانائی کا حساب کیسے لگاتے ہیں؟","howAnswer":"کائنےٹک انرجی ماس ٹائم اسپیڈ اسکوائر کا نصف ہے: KE = ½mv²۔ \nکسی منتخب اونچائی کے نسبت کشش ثقل کی ممکنہ توانائی PE = mgh ہے۔ \nمثال کے طور پر، 3 m/s کی رفتار سے حرکت کرنے والی 2 کلوگرام شے میں 9 J حرکی توانائی ہوتی ہے۔ \nدکھایا گیا کل ان مثالی اقدار کا مجموعہ ہے، ایسی پیشین گوئی نہیں جس میں رگڑ یا دیگر نقصانات شامل ہوں۔","privacyQuestion":"کیا میری اقدار اپ لوڈ ہیں؟","privacyAnswer":"نمبر۔ حساب اس براؤزر میں مقامی طور پر چلتا ہے۔ \nاقدار اپ لوڈ یا محفوظ نہیں ہیں۔","fields":{"mode":"کیلکولیشن موڈ","energyMode":"رفتار سے توانائی کا حساب لگائیں۔","speedMode":"حرکی توانائی سے رفتار حل کریں۔","massKg":"ماس (کلوگرام)","velocityMps":"رفتار (m/s)","kineticEnergyJ":"حرکی توانائی (J)","heightM":"صفر سے اوپر کی اونچائی (میٹر)","gravityMps2":"کشش ثقل کی سرعت (m/s²)","accuracyNote":"آپ کے منتخب کردہ صفر کی سطح کے نسبت اونچائی کا استعمال کریں۔ \nکشش ثقل 9.80665 m/s² پر ڈیفالٹ ہے لیکن اسے تبدیل کیا جا سکتا ہے۔ \nیہ مثالی تخمینہ رگڑ، ہوا کی مزاحمت، گردش اور رشتہ داری کے اثرات کو نظر انداز کرتا ہے۔ \nیہ انجینئرنگ یا حفاظتی تشخیص نہیں ہے۔"},"actions":{"calculate":"توانائی کا حساب لگائیں۔","reset":"ری سیٹ کریں۔","copy":"نتیجہ کاپی کریں۔","example":"2 کلوگرام 3 میٹر فی سیکنڈ پر آزمائیں","result":"توانائی کا نتیجہ"},"messages":{"calculated":"حساب تیار ہے۔","checkInputs":"ایک مثبت ماس ​​اور درست رفتار یا حرکی توانائی درج کریں۔ \nاونچائی منفی ہو سکتی ہے؛ \nکشش ثقل صفر سے زیادہ ہونی چاہیے۔","velocity":"رفتار","kineticEnergy":"حرکی توانائی","potentialEnergy":"کشش ثقل ممکنہ توانائی","totalEnergy":"کل مکینیکل توانائی"},"additionalFaqs":[{"question":"کیا میں حرکی توانائی سے رفتار تلاش کر سکتا ہوں؟","answer":"ہاں۔ \n\"متحرک توانائی سے رفتار حل کریں\" کو منتخب کریں، پھر ایک مثبت کمیت اور صفر یا اس سے زیادہ کی حرکی توانائی کی قدر درج کریں۔ \nکیلکولیٹر v = √(2KE/m) استعمال کرتا ہے۔"},{"question":"ممکنہ توانائی منفی کیوں ہو سکتی ہے؟","answer":"ممکنہ توانائی کی پیمائش آپ کے منتخب کردہ حوالہ اونچائی سے کی جاتی ہے۔ \nصفر کی سطح سے نیچے کی پوزیشن منفی mgh ہے؛ \nاس کا مطلب یہ نہیں ہے کہ شے کا کمیت منفی ہے یا حرکی توانائی منفی ہے۔"},{"question":"کیا کل مکینیکل توانائی میں توانائی کے نقصانات شامل ہیں؟","answer":"نمبر۔ یہ صرف حرکی اور کشش ثقل کی ممکنہ توانائی کا مجموعہ ہے۔ \nرگڑ، ہوا کی مزاحمت، گردش، اخترتی اور دیگر توانائی کی منتقلی کا نمونہ نہیں بنایا گیا ہے۔"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"tr":{"copyLanguage":"tr","name":"Kinetik Enerji Hesaplayıcı","title":"Kinetik Enerji Hesaplayıcı | UsefulVerse","description":"Kinetik ve potansiyel enerjiyi hesaplayın veya enerjiden hızı çözün. \nÜcretsiz, yerel ve hesap yok.","intro":"Kütle ve hızdan kinetik enerjiyi, yükseklikten yerçekimi potansiyel enerjisini hesaplayın veya bilinen bir kinetik enerjiden hızı çözün. \nTahmin için kullanılan sıfır yükseklik referansını ve yerçekimini seçin.","howQuestion":"Kinetik enerjiyi nasıl hesaplarsınız?","howAnswer":"Kinetik enerji, kütle çarpı hızın karesinin yarısıdır: KE = ½mv². \nSeçilen bir yüksekliğe göre yer çekimi potansiyel enerjisi PE = mgh'tir. \nÖrneğin, 3 m/s hızla hareket eden 2 kg'lık bir nesnenin 9 J kinetik enerjisi vardır. \nGösterilen toplam, bu idealleştirilmiş değerlerin toplamıdır; sürtünme veya diğer kayıpları içeren bir tahmin değildir.","privacyQuestion":"Değerlerim yüklendi mi?","privacyAnswer":"Hayır. Hesaplama bu tarayıcıda yerel olarak çalışır; \ndeğerler yüklenmez veya kaydedilmez.","fields":{"mode":"Hesaplama modu","energyMode":"Hızdan enerjiyi hesaplayın","speedMode":"Kinetik enerjiden hızı çözme","massKg":"Kütle (kg)","velocityMps":"Hız (m/s)","kineticEnergyJ":"Kinetik enerji (J)","heightM":"Sıfır referansının üzerindeki yükseklik (m)","gravityMps2":"Yerçekimi ivmesi (m/s²)","accuracyNote":"Seçtiğiniz sıfır düzeyine göre yüksekliği kullanın. \nYerçekimi varsayılan olarak 9.80665 m/s²'tir ancak değiştirilebilir. \nBu ideal tahmin sürtünmeyi, hava direncini, dönmeyi ve göreceli etkileri göz ardı eder; \nbu bir mühendislik veya güvenlik değerlendirmesi değildir."},"actions":{"calculate":"Enerjiyi hesaplayın","reset":"Sıfırla","copy":"Sonucu kopyala","example":"3 m/s'de 2 kg'ı deneyin","result":"Enerji sonucu"},"messages":{"calculated":"Hesaplama hazır.","checkInputs":"Pozitif bir kütle ve geçerli bir hız veya kinetik enerji girin. \nYükseklik negatif olabilir; \nyerçekimi sıfırdan büyük olmalıdır.","velocity":"Hız","kineticEnergy":"Kinetik enerji","potentialEnergy":"Yerçekimi potansiyel enerjisi","totalEnergy":"Toplam mekanik enerji"},"additionalFaqs":[{"question":"Kinetik enerjiden hız bulabilir miyim?","answer":"Evet. \n\"Hızı kinetik enerjiden çöz\" seçeneğini seçin, ardından pozitif bir kütle ve sıfır veya daha büyük bir kinetik enerji değeri girin. \nHesap makinesi v = √(2KE/m) kullanır."},{"question":"Potansiyel enerji neden negatif olabilir?","answer":"Potansiyel enerji, seçtiğiniz bir referans yüksekliğine göre ölçülür. \nBu sıfır seviyesinin altındaki bir pozisyon negatif mgh'ye sahiptir; \nbu, nesnenin negatif kütleye sahip olduğu veya kinetik enerjisinin negatif olduğu anlamına gelmez."},{"question":"Toplam mekanik enerjiye enerji kayıpları da dahil mi?","answer":"Hayır. Yalnızca kinetik ve çekim potansiyel enerjisinin toplamıdır. \nSürtünme, hava direnci, dönme, deformasyon ve diğer enerji transferleri modellenmemiştir."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"vi":{"copyLanguage":"vi","name":"Máy tính động năng","title":"Máy tính động năng | UsefulVerse","description":"Tính động năng và thế năng hoặc giải tốc độ từ năng lượng. \nMiễn phí, địa phương và không có tài khoản.","intro":"Tính động năng từ khối lượng và tốc độ, thế năng hấp dẫn từ độ cao hoặc giải tốc độ từ động năng đã biết. \nChọn tham chiếu độ cao bằng 0 và trọng lực được sử dụng để ước tính.","howQuestion":"Bạn tính động năng như thế nào?","howAnswer":"Động năng bằng một nửa khối lượng nhân với bình phương tốc độ: KE = ½mv². \nThế năng hấp dẫn tương ứng với độ cao đã chọn là PE = mgh. \nVí dụ, một vật có khối lượng 2 kg chuyển động với vận tốc 3 m/s thì có động năng là 9 J. \nTổng số hiển thị là tổng của các giá trị lý tưởng hóa này, không phải là dự đoán bao gồm ma sát hoặc tổn thất khác.","privacyQuestion":"Giá trị của tôi có được tải lên không?","privacyAnswer":"Không. Phép tính chạy cục bộ trong trình duyệt này; \ncác giá trị không được tải lên hoặc lưu.","fields":{"mode":"Chế độ tính toán","energyMode":"Tính năng lượng từ tốc độ","speedMode":"Giải tốc độ từ động năng","massKg":"Khối lượng (kg)","velocityMps":"Tốc độ (m/s)","kineticEnergyJ":"Động năng (J)","heightM":"Chiều cao trên tham chiếu 0 (m)","gravityMps2":"Gia tốc trọng trường (m/s²)","accuracyNote":"Sử dụng chiều cao tương ứng với mức 0 mà bạn đã chọn. \nTrọng lực mặc định là 9.80665 m/s² nhưng có thể thay đổi. \nƯớc tính lý tưởng này bỏ qua các hiệu ứng ma sát, lực cản không khí, chuyển động quay và thuyết tương đối tính; \nnó không phải là một đánh giá kỹ thuật hoặc an toàn."},"actions":{"calculate":"Tính năng lượng","reset":"Đặt lại","copy":"Sao chép kết quả","example":"Thử 2 kg với tốc độ 3 m/s","result":"Kết quả năng lượng"},"messages":{"calculated":"Tính toán đã sẵn sàng.","checkInputs":"Nhập khối lượng dương và tốc độ hoặc động năng hợp lệ. \nChiều cao có thể âm; \ntrọng lực phải lớn hơn 0.","velocity":"Tốc độ","kineticEnergy":"Động năng","potentialEnergy":"Thế năng hấp dẫn","totalEnergy":"Tổng cơ năng"},"additionalFaqs":[{"question":"Tôi có thể tìm tốc độ từ động năng không?","answer":"Có. \nChọn “Giải tốc độ từ động năng”, sau đó nhập khối lượng dương và giá trị động năng bằng 0 hoặc lớn hơn. \nMáy tính sử dụng v = √(2KE/m)."},{"question":"Tại sao thế năng có thể âm?","answer":"Thế năng được đo tương ứng với độ cao tham chiếu mà bạn chọn. \nMột vị trí dưới mức 0 đó có mgh âm; \nđiều này không có nghĩa là vật có khối lượng âm hoặc động năng âm."},{"question":"Tổng năng lượng cơ học có bao gồm tổn thất năng lượng không?","answer":"Không. Nó chỉ là tổng động năng và thế năng hấp dẫn. \nMa sát, lực cản không khí, chuyển động quay, biến dạng và các sự truyền năng lượng khác không được mô hình hóa."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"it":{"copyLanguage":"it","name":"Calcolatore dell'energia cinetica","title":"Calcolatore dell'energia cinetica | UsefulVerse","description":"Calcola l'energia cinetica e potenziale o risolvi la velocità dall'energia. \nGratuito, locale e senza account.","intro":"Calcola l'energia cinetica dalla massa e dalla velocità, l'energia potenziale gravitazionale dall'altezza o risolvi la velocità da un'energia cinetica nota. \nScegli il riferimento ad altezza zero e la gravità utilizzati per la stima.","howQuestion":"Come si calcola l'energia cinetica?","howAnswer":"L'energia cinetica è la metà della massa per la velocità al quadrato: KE = ½mv². \nL'energia potenziale gravitazionale relativa ad un'altezza scelta è PE = mgh. \nAd esempio, un oggetto di 2 kg che si muove a 3 m/s ha 9 J di energia cinetica. \nIl totale mostrato è la somma di questi valori idealizzati, non una previsione che include attriti o altre perdite.","privacyQuestion":"I miei valori sono caricati?","privacyAnswer":"No. Il calcolo viene eseguito localmente in questo browser; \ni valori non vengono caricati né salvati.","fields":{"mode":"Modalità di calcolo","energyMode":"Calcola l'energia dalla velocità","speedMode":"Risolvi la velocità dall'energia cinetica","massKg":"Massa (kg)","velocityMps":"Velocità (m/s)","kineticEnergyJ":"Energia cinetica (J)","heightM":"Altezza sopra lo zero di riferimento (m)","gravityMps2":"Accelerazione gravitazionale (m/s²)","accuracyNote":"Usa l'altezza relativa al livello zero scelto. \nLa gravità per impostazione predefinita è 9.80665 m/s² ma può essere modificata. \nQuesta stima ideale ignora l'attrito, la resistenza dell'aria, la rotazione e gli effetti relativistici; \nnon è una valutazione tecnica o di sicurezza."},"actions":{"calculate":"Calcola l'energia","reset":"Ripristina","copy":"Copia risultato","example":"Prova 2 kg a 3 m/s","result":"Risultato energetico"},"messages":{"calculated":"Calcolo pronto.","checkInputs":"Inserisci una massa positiva e una velocità o un'energia cinetica valide. \nL'altezza può essere negativa; \nla gravità deve essere maggiore di zero.","velocity":"Velocità","kineticEnergy":"Energia cinetica","potentialEnergy":"Energia potenziale gravitazionale","totalEnergy":"Energia meccanica totale"},"additionalFaqs":[{"question":"Posso trovare la velocità dall'energia cinetica?","answer":"Sì. \nSeleziona \"Risolvi la velocità dall'energia cinetica\", quindi inserisci una massa positiva e un valore di energia cinetica pari a zero o superiore. \nLa calcolatrice utilizza v = √(2KE/m)."},{"question":"Perché l'energia potenziale può essere negativa?","answer":"L'energia potenziale viene misurata rispetto a un'altezza di riferimento scelta. \nUna posizione al di sotto del livello zero ha mgh negativo; \nquesto non significa che l'oggetto abbia massa negativa o che l'energia cinetica sia negativa."},{"question":"L'energia meccanica totale include le perdite di energia?","answer":"No. È solo la somma dell'energia potenziale cinetica e gravitazionale. \nL'attrito, la resistenza dell'aria, la rotazione, la deformazione e altri trasferimenti di energia non sono modellati."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"zh_tw":{"copyLanguage":"zh_tw","name":"動能計算器","title":"動能計算器 | UsefulVerse","description":"計算動能和位能或根據能量求解速度。免費、本地且無需帳戶。","intro":"根據質量和速度計算動能，根據高度計算重力位能，或根據已知動能求解速度。選擇用於估計的零高度參考和重力。","howQuestion":"如何計算動能？","howAnswer":"動能是質量乘以速度平方的一半：KE = ½mv²。相對於選定高度的重力位能是 PE = mgh。例如，以 3 m/s 速率運動的 2 kg 物體具有 9 J 的動能。顯示的總數是這些理想值的總和，而不是包含摩擦或其他損失的預測。","privacyQuestion":"我的值上傳了嗎？","privacyAnswer":"否。計算在此瀏覽器中本地運行；這些值不會上傳或保存。","fields":{"mode":"計算模式","energyMode":"依速度計算能量","speedMode":"從動能求解速度","massKg":"質量（公斤）","velocityMps":"速度（公尺/秒）","kineticEnergyJ":"動能 (J)","heightM":"零參考上方的高度 (m)","gravityMps2":"重力加速度 (m/s²)","accuracyNote":"使用相對於您選擇的零水平的高度。重力預設為 9.80665 m/s²，但可以更改。這種理想的估計忽略了摩擦、空氣阻力、旋轉和相對論效應；它不是工程或安全評估。"},"actions":{"calculate":"計算能量","reset":"重置","copy":"複製結果","example":"嘗試以 3 m/s 的速度載入 2 kg","result":"能量結果"},"messages":{"calculated":"計算就緒。","checkInputs":"輸入正質量和有效速度或動能。高度可以是負值；重力必須大於零。","velocity":"速度","kineticEnergy":"動能","potentialEnergy":"重力位能","totalEnergy":"總機械能"},"additionalFaqs":[{"question":"我可以從動能中求出速度嗎？","answer":"是的。選擇“根據動能求解速度”，然後輸入正質量和零或更大的動能值。計算器使用v = √(2KE/m)。"},{"question":"為什麼位能可以是負值？","answer":"位能是相對於您選擇的參考高度進行測量的。低於該零水平的位置具有負 mgh；這並不意味著該物體具有負質量或動能為負。"},{"question":"總機械能包括能量損失嗎？","answer":"否。它只是動能和重力位能的總和。摩擦、空氣阻力、旋轉、變形和其他能量傳遞沒有建模。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"bg":{"copyLanguage":"bg","name":"Калкулатор за кинетична енергия","title":"Калкулатор за кинетична енергия | UsefulVerse","description":"Изчислете кинетичната и потенциалната енергия или разрешете скоростта от енергията. \nБезплатно, локално и без акаунт.","intro":"Изчислете кинетичната енергия от масата и скоростта, гравитационната потенциална енергия от височината или разрешете скоростта от известна кинетична енергия. \nИзберете референтната нулева височина и гравитацията, използвани за оценката.","howQuestion":"Как изчислявате кинетичната енергия?","howAnswer":"Кинетичната енергия е половината от масата по скоростта на квадрат: KE = ½mv². \nГравитационната потенциална енергия спрямо избрана височина е PE = mgh. \nНапример, обект от 2 kg, който се движи с 3 m/s, има 9 J кинетична енергия. \nПоказаната обща сума е сумата от тези идеализирани стойности, а не прогноза, която включва триене или други загуби.","privacyQuestion":"Моите стойности качени ли са?","privacyAnswer":"Не. Изчислението се изпълнява локално в този браузър; \nстойностите не се качват или записват.","fields":{"mode":"Режим на изчисление","energyMode":"Изчислете енергията от скоростта","speedMode":"Разрешете скоростта от кинетичната енергия","massKg":"Маса (кг)","velocityMps":"Скорост (m/s)","kineticEnergyJ":"Кинетична енергия (J)","heightM":"Височина над нулевата референтна точка (m)","gravityMps2":"Гравитационно ускорение (m/s²)","accuracyNote":"Използвайте височина спрямо избраното от вас нулево ниво. \nГравитацията по подразбиране е 9.80665 m/s², но може да бъде променена. \nТази идеална оценка пренебрегва триенето, съпротивлението на въздуха, въртенето и релативистичните ефекти; \nтова не е инженерна оценка или оценка на безопасността."},"actions":{"calculate":"Изчислете енергия","reset":"Нулиране","copy":"Копиране на резултата","example":"Опитайте 2 kg при 3 m/s","result":"Енергиен резултат"},"messages":{"calculated":"Изчислението е готово.","checkInputs":"Въведете положителна маса и валидна скорост или кинетична енергия. \nВисочината може да е отрицателна; \nгравитацията трябва да е по-голяма от нула.","velocity":"Скорост","kineticEnergy":"Кинетична енергия","potentialEnergy":"Гравитационна потенциална енергия","totalEnergy":"Обща механична енергия"},"additionalFaqs":[{"question":"Мога ли да намеря скорост от кинетичната енергия?","answer":"Да. \nИзберете „Разрешаване на скорост от кинетична енергия“, след което въведете положителна маса и стойност на кинетичната енергия нула или по-голяма. \nКалкулаторът използва v = √(2KE/m)."},{"question":"Защо потенциалната енергия може да бъде отрицателна?","answer":"Потенциалната енергия се измерва спрямо референтна височина, която изберете. \nПозиция под това нулево ниво има отрицателен mgh; \nтова не означава, че обектът има отрицателна маса или че кинетичната енергия е отрицателна."},{"question":"Общата механична енергия включва ли загуби на енергия?","answer":"Не. Това е сбор само от кинетична и гравитационна потенциална енергия. \nТриенето, съпротивлението на въздуха, въртенето, деформацията и други трансфери на енергия не се моделират."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ca":{"copyLanguage":"ca","name":"Calculadora d'energia cinètica","title":"Calculadora d'energia cinètica | UsefulVerse","description":"Calcula l'energia cinètica i potencial o resol la velocitat a partir d'energia. \nGratuït, local i sense compte.","intro":"Calcula l'energia cinètica a partir de la massa i la velocitat, l'energia potencial gravitatòria des de l'alçada o resol la velocitat a partir d'una energia cinètica coneguda. \nTrieu la referència d'alçada zero i la gravetat utilitzades per a l'estimació.","howQuestion":"Com es calcula l'energia cinètica?","howAnswer":"L'energia cinètica és la meitat de la massa multiplicada per la velocitat al quadrat: KE = ½mv². \nL'energia potencial gravitatòria relativa a una alçada escollida és PE = mgh. \nPer exemple, un objecte de 2 kg que es mou a 3 m/s té 9 J d'energia cinètica. \nEl total mostrat és la suma d'aquests valors idealitzats, no una predicció que inclogui la fricció o altres pèrdues.","privacyQuestion":"S'han penjat els meus valors?","privacyAnswer":"No. El càlcul s'executa localment en aquest navegador; \nels valors no es carreguen ni es guarden.","fields":{"mode":"Mode de càlcul","energyMode":"Calcula l'energia a partir de la velocitat","speedMode":"Resoldre la velocitat a partir de l'energia cinètica","massKg":"Massa (kg)","velocityMps":"Velocitat (m/s)","kineticEnergyJ":"Energia cinètica (J)","heightM":"Alçada per sobre de la referència zero (m)","gravityMps2":"Acceleració gravitatòria (m/s²)","accuracyNote":"Utilitzeu l'alçada relativa al nivell zero triat. \nLa gravetat és 9.80665 m/s² per defecte, però es pot canviar. \nAquesta estimació ideal ignora la fricció, la resistència de l'aire, la rotació i els efectes relativistes; \nno és una avaluació d'enginyeria o de seguretat."},"actions":{"calculate":"Calcula l'energia","reset":"Restableix","copy":"Copia el resultat","example":"Prova 2 kg a 3 m/s","result":"Resultat energètic"},"messages":{"calculated":"Càlcul preparat.","checkInputs":"Introduïu una massa positiva i una velocitat o energia cinètica vàlida. \nL'alçada pot ser negativa; \nla gravetat ha de ser superior a zero.","velocity":"Velocitat","kineticEnergy":"Energia cinètica","potentialEnergy":"Energia potencial gravitatòria","totalEnergy":"Energia mecànica total"},"additionalFaqs":[{"question":"Puc trobar la velocitat a partir de l'energia cinètica?","answer":"Sí. \nSeleccioneu \"Resol la velocitat a partir de l'energia cinètica\" i introduïu una massa positiva i un valor d'energia cinètica igual o superior a zero. \nLa calculadora utilitza v = √(2KE/m)."},{"question":"Per què l'energia potencial pot ser negativa?","answer":"L'energia potencial es mesura en relació a una alçada de referència que trieu. \nUna posició per sota d'aquest nivell zero té mgh negatiu; \naixò no vol dir que l'objecte tingui massa negativa o que l'energia cinètica sigui negativa."},{"question":"L'energia mecànica total inclou les pèrdues d'energia?","answer":"No. Només és la suma de l'energia potencial cinètica i gravitatòria. \nNo es modelen la fricció, la resistència de l'aire, la rotació, la deformació i altres transferències d'energia."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"nl":{"copyLanguage":"nl","name":"Kinetische energiecalculator","title":"Kinetische energiecalculator | UsefulVerse","description":"Calculate kinetic and potential energy or solve speed from energy. \nGratis, lokaal en zonder account.","intro":"Bereken kinetische energie uit massa en snelheid, potentiële zwaartekrachtenergie uit hoogte, of los snelheid op uit een bekende kinetische energie. \nChoose the zero-height reference and gravity used for the estimate.","howQuestion":"How do you calculate kinetic energy?","howAnswer":"Kinetic energy is one half of mass times speed squared: KE = ½mv². \nGravitational potential energy relative to a chosen height is PE = mgh. \nFor example, a 2 kg object moving at 3 m/s has 9 J of kinetic energy. \nThe total shown is the sum of these idealized values, not a prediction that includes friction or other losses.","privacyQuestion":"Zijn mijn waarden geüpload?","privacyAnswer":"No. The calculation runs locally in this browser; \nde waarden worden niet geüpload of opgeslagen.","fields":{"mode":"Berekeningsmodus","energyMode":"Bereken energie uit snelheid","speedMode":"Los snelheid op uit kinetische energie","massKg":"Massa (kg)","velocityMps":"Snelheid (m/s)","kineticEnergyJ":"Kinetische energie (J)","heightM":"Hoogte boven de nulreferentie (m)","gravityMps2":"Zwaartekrachtversnelling (m/s²)","accuracyNote":"Gebruik de hoogte ten opzichte van het door u gekozen nulniveau. \nDe zwaartekracht is standaard ingesteld op 9.80665 m/s², maar kan worden gewijzigd. \nDeze ideale schatting negeert wrijving, luchtweerstand, rotatie en relativistische effecten; \nhet is geen technische of veiligheidsbeoordeling."},"actions":{"calculate":"Bereken energie","reset":"Opnieuw instellen","copy":"Resultaat kopiëren","example":"Probeer 2 kg bij 3 m/s","result":"Energieresultaat"},"messages":{"calculated":"Berekening gereed.","checkInputs":"Voer een positieve massa en geldige snelheid of kinetische energie in. \nHoogte kan negatief zijn; \nDe zwaartekracht moet groter zijn dan nul.","velocity":"Snelheid","kineticEnergy":"Kinetische energie","potentialEnergy":"Potentiële zwaartekrachtenergie","totalEnergy":"Totale mechanische energie"},"additionalFaqs":[{"question":"Kan ik snelheid uit kinetische energie halen?","answer":"Ja. \nSelecteer 'Snelheid oplossen uit kinetische energie' en voer vervolgens een positieve massa en een kinetische energiewaarde van nul of hoger in. \nDe rekenmachine maakt gebruik van v = √(2KE/m)."},{"question":"Waarom kan potentiële energie negatief zijn?","answer":"Potentiële energie wordt gemeten ten opzichte van een referentiehoogte die u kiest. \nEen positie onder dat nulniveau heeft een negatieve mgh; \ndit betekent niet dat het object een negatieve massa heeft of dat de kinetische energie negatief is."},{"question":"Omvat de totale mechanische energie energieverliezen?","answer":"Nee. Het is alleen de som van kinetische en zwaartekracht-potentiële energie. \nWrijving, luchtweerstand, rotatie, vervorming en andere energieoverdrachten worden niet gemodelleerd."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"el":{"copyLanguage":"el","name":"Υπολογιστής Κινητικής Ενέργειας","title":"Υπολογιστής Κινητικής Ενέργειας | UsefulVerse","description":"Υπολογίστε την κινητική και δυναμική ενέργεια ή λύστε την ταχύτητα από ενέργεια. \nΔωρεάν, τοπικό και χωρίς λογαριασμό.","intro":"Υπολογίστε την κινητική ενέργεια από τη μάζα και την ταχύτητα, τη βαρυτική δυναμική ενέργεια από το ύψος ή να λύσετε την ταχύτητα από μια γνωστή κινητική ενέργεια. \nΕπιλέξτε την αναφορά μηδενικού ύψους και τη βαρύτητα που χρησιμοποιούνται για την εκτίμηση.","howQuestion":"Πώς υπολογίζετε την κινητική ενέργεια;","howAnswer":"Η κινητική ενέργεια είναι το μισό της μάζας επί το τετράγωνο της ταχύτητας: KE = ½mv². \nΗ βαρυτική δυναμική ενέργεια σε σχέση με ένα επιλεγμένο ύψος είναι PE = mgh. \nΓια παράδειγμα, ένα αντικείμενο 2 kg που κινείται με ταχύτητα 3 m/s έχει 9 J κινητικής ενέργειας. \nΤο σύνολο που εμφανίζεται είναι το άθροισμα αυτών των εξιδανικευμένων τιμών, όχι μια πρόβλεψη που περιλαμβάνει τριβές ή άλλες απώλειες.","privacyQuestion":"Έχουν μεταφορτωθεί οι τιμές μου;","privacyAnswer":"Όχι. Ο υπολογισμός εκτελείται τοπικά σε αυτό το πρόγραμμα περιήγησης. \nοι τιμές δεν μεταφορτώνονται ούτε αποθηκεύονται.","fields":{"mode":"Λειτουργία υπολογισμού","energyMode":"Υπολογίστε την ενέργεια από την ταχύτητα","speedMode":"Επίλυση ταχύτητας από κινητική ενέργεια","massKg":"Μάζα (kg)","velocityMps":"Ταχύτητα (m/s)","kineticEnergyJ":"Κινητική ενέργεια (J)","heightM":"Ύψος πάνω από το μηδέν αναφοράς (m)","gravityMps2":"Βαρυτική επιτάχυνση (m/s²)","accuracyNote":"Χρησιμοποιήστε το ύψος σε σχέση με το μηδενικό επίπεδο που έχετε επιλέξει. \nΤο Gravity έχει οριστεί από προεπιλογή σε 9.80665 m/s², αλλά μπορεί να αλλάξει. \nΑυτή η ιδανική εκτίμηση αγνοεί την τριβή, την αντίσταση του αέρα, την περιστροφή και τις σχετικιστικές επιδράσεις. \nδεν είναι αξιολόγηση μηχανικής ή ασφάλειας."},"actions":{"calculate":"Υπολογίστε την ενέργεια","reset":"Επαναφορά","copy":"Αντιγραφή αποτελέσματος","example":"Δοκιμάστε 2 κιλά με 3 m/s","result":"Ενεργειακό αποτέλεσμα"},"messages":{"calculated":"Έτοιμος ο υπολογισμός.","checkInputs":"Εισαγάγετε θετική μάζα και έγκυρη ταχύτητα ή κινητική ενέργεια. \nΤο ύψος μπορεί να είναι αρνητικό. \nη βαρύτητα πρέπει να είναι μεγαλύτερη από το μηδέν.","velocity":"Ταχύτητα","kineticEnergy":"Κινητική ενέργεια","potentialEnergy":"Δυναμική ενέργεια βαρύτητας","totalEnergy":"Ολική μηχανική ενέργεια"},"additionalFaqs":[{"question":"Μπορώ να βρω ταχύτητα από την κινητική ενέργεια;","answer":"Ναι. \nΕπιλέξτε «Επίλυση ταχύτητας από κινητική ενέργεια» και, στη συνέχεια, εισαγάγετε μια θετική μάζα και μια τιμή κινητικής ενέργειας μηδέν ή μεγαλύτερη. \nΗ αριθμομηχανή χρησιμοποιεί v = √(2KE/m)."},{"question":"Γιατί η δυνητική ενέργεια μπορεί να είναι αρνητική;","answer":"Η δυναμική ενέργεια μετριέται σε σχέση με ένα ύψος αναφοράς που επιλέγετε. \nΜια θέση κάτω από αυτό το μηδενικό επίπεδο έχει αρνητικό mgh. \nΑυτό δεν σημαίνει ότι το αντικείμενο έχει αρνητική μάζα ή ότι η κινητική ενέργεια είναι αρνητική."},{"question":"Η συνολική μηχανική ενέργεια περιλαμβάνει τις απώλειες ενέργειας;","answer":"Όχι. Είναι το άθροισμα μόνο της δυναμικής κινητικής και βαρυτικής ενέργειας. \nΗ τριβή, η αντίσταση του αέρα, η περιστροφή, η παραμόρφωση και άλλες μεταφορές ενέργειας δεν μοντελοποιούνται."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ms":{"copyLanguage":"ms","name":"Kalkulator Tenaga Kinetik","title":"Kalkulator Tenaga Kinetik | UsefulVerse","description":"Kira tenaga kinetik dan keupayaan atau selesaikan kelajuan daripada tenaga. \nPercuma, tempatan dan tiada akaun.","intro":"Kira tenaga kinetik daripada jisim dan kelajuan, tenaga keupayaan graviti daripada ketinggian, atau selesaikan kelajuan daripada tenaga kinetik yang diketahui. \nPilih rujukan ketinggian sifar dan graviti yang digunakan untuk anggaran.","howQuestion":"Bagaimanakah anda mengira tenaga kinetik?","howAnswer":"Tenaga kinetik ialah satu separuh daripada kelajuan masa jisim kuasa dua: KE = ½mv². \nTenaga keupayaan graviti berbanding ketinggian yang dipilih ialah PE = mgh. \nSebagai contoh, objek 2 kg bergerak pada 3 m/s mempunyai 9 J tenaga kinetik. \nJumlah yang ditunjukkan ialah jumlah nilai ideal ini, bukan ramalan yang merangkumi geseran atau kerugian lain.","privacyQuestion":"Adakah nilai saya dimuat naik?","privacyAnswer":"Tidak. Pengiraan dijalankan secara setempat dalam penyemak imbas ini; \nnilai tidak dimuat naik atau disimpan.","fields":{"mode":"Mod pengiraan","energyMode":"Kira tenaga daripada kelajuan","speedMode":"Selesaikan kelajuan daripada tenaga kinetik","massKg":"Jisim (kg)","velocityMps":"Kelajuan (m/s)","kineticEnergyJ":"Tenaga kinetik (J)","heightM":"Ketinggian di atas rujukan sifar (m)","gravityMps2":"Pecutan graviti (m/s²)","accuracyNote":"Gunakan ketinggian berbanding tahap sifar pilihan anda. \nGraviti lalai kepada 9.80665 m/s² tetapi boleh ditukar. \nAnggaran ideal ini mengabaikan geseran, rintangan udara, putaran dan kesan relativistik; \nia bukan penilaian kejuruteraan atau keselamatan."},"actions":{"calculate":"Kira tenaga","reset":"Tetapkan semula","copy":"Salin keputusan","example":"Cuba 2 kg pada 3 m/s","result":"Hasil tenaga"},"messages":{"calculated":"Pengiraan sedia.","checkInputs":"Masukkan jisim positif dan kelajuan sah atau tenaga kinetik. \nKetinggian mungkin negatif; \ngraviti mestilah lebih besar daripada sifar.","velocity":"Kelajuan","kineticEnergy":"Tenaga kinetik","potentialEnergy":"Tenaga keupayaan graviti","totalEnergy":"Jumlah tenaga mekanikal"},"additionalFaqs":[{"question":"Bolehkah saya mencari kelajuan daripada tenaga kinetik?","answer":"Ya. \nPilih \"Selesaikan kelajuan daripada tenaga kinetik,\" kemudian masukkan jisim positif dan nilai tenaga kinetik sifar atau lebih besar. \nKalkulator menggunakan v = √(2KE/m)."},{"question":"Mengapakah tenaga berpotensi boleh menjadi negatif?","answer":"Tenaga potensi diukur secara relatif kepada ketinggian rujukan yang anda pilih. \nKedudukan di bawah paras sifar itu mempunyai mgh negatif; \nini tidak bermakna objek mempunyai jisim negatif atau tenaga kinetik adalah negatif."},{"question":"Adakah jumlah tenaga mekanikal termasuk kehilangan tenaga?","answer":"Tidak. Ia adalah jumlah tenaga keupayaan kinetik dan graviti sahaja. \nGeseran, rintangan udara, putaran, ubah bentuk dan pemindahan tenaga lain tidak dimodelkan."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"pl":{"copyLanguage":"pl","name":"Kalkulator energii kinetycznej","title":"Kalkulator energii kinetycznej | UsefulVerse","description":"Oblicz energię kinetyczną i potencjalną lub oblicz prędkość na podstawie energii. \nBezpłatnie, lokalnie i bez konta.","intro":"Oblicz energię kinetyczną na podstawie masy i prędkości, energię potencjalną grawitacji na podstawie wysokości lub oblicz prędkość na podstawie znanej energii kinetycznej. \nWybierz odniesienie o zerowej wysokości i grawitację użyte do oszacowania.","howQuestion":"Jak obliczyć energię kinetyczną?","howAnswer":"Energia kinetyczna to połowa masy razy kwadrat prędkości: KE = ½mv². \nEnergia potencjalna grawitacji w odniesieniu do wybranej wysokości wynosi PE = mgh. \nNa przykład obiekt o masie 2 kg poruszający się z prędkością 3 m/s ma energię kinetyczną 9 J. \nWyświetlana suma jest sumą tych wyidealizowanych wartości, a nie przewidywaniem uwzględniającym tarcie lub inne straty.","privacyQuestion":"Czy moje wartości zostały przesłane?","privacyAnswer":"Nie. Kalkulacja przebiega lokalnie w tej przeglądarce; \nwartości nie są przesyłane ani zapisywane.","fields":{"mode":"Tryb obliczeń","energyMode":"Oblicz energię na podstawie prędkości","speedMode":"Oblicz prędkość na podstawie energii kinetycznej","massKg":"Masa (kg)","velocityMps":"Prędkość (m/s)","kineticEnergyJ":"Energia kinetyczna (J)","heightM":"Wysokość powyżej zera odniesienia (m)","gravityMps2":"Przyspieszenie grawitacyjne (m/s²)","accuracyNote":"Użyj wysokości w stosunku do wybranego poziomu zerowego. \nDomyślną wartością grawitacji jest 9.80665 m/s², ale można ją zmienić. \nTo idealne oszacowanie ignoruje tarcie, opór powietrza, rotację i efekty relatywistyczne; \nnie jest to ocena inżynieryjna ani bezpieczeństwa."},"actions":{"calculate":"Oblicz energię","reset":"Resetuj","copy":"Skopiuj wynik","example":"Wypróbuj 2 kg przy 3 m/s","result":"Wynik energetyczny"},"messages":{"calculated":"Kalkulacja gotowa.","checkInputs":"Podaj dodatnią masę i prawidłową prędkość lub energię kinetyczną. \nWysokość może być ujemna; \ngrawitacja musi być większa od zera.","velocity":"Prędkość","kineticEnergy":"Energia kinetyczna","potentialEnergy":"Energia potencjalna grawitacji","totalEnergy":"Całkowita energia mechaniczna"},"additionalFaqs":[{"question":"Czy mogę znaleźć prędkość na podstawie energii kinetycznej?","answer":"Tak. \nWybierz opcję „Rozwiąż prędkość na podstawie energii kinetycznej”, a następnie wprowadź dodatnią masę i wartość energii kinetycznej wynoszącą zero lub większą. \nKalkulator wykorzystuje v = √(2KE/m)."},{"question":"Dlaczego energia potencjalna może być ujemna?","answer":"Energia potencjalna mierzona jest w odniesieniu do wybranej przez Ciebie wysokości odniesienia. \nPozycja poniżej tego poziomu zerowego ma ujemną mgh; \nnie oznacza to, że obiekt ma ujemną masę lub że energia kinetyczna jest ujemna."},{"question":"Czy całkowita energia mechaniczna obejmuje straty energii?","answer":"Nie. Jest to suma wyłącznie energii potencjalnej kinetycznej i grawitacyjnej. \nNie modeluje się tarcia, oporu powietrza, rotacji, odkształcenia i innych transferów energii."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"sv":{"copyLanguage":"sv","name":"Kinetisk energikalkylator","title":"Kinetisk energikalkylator | UsefulVerse","description":"Beräkna kinetisk och potentiell energi eller lös hastighet från energi. \nGratis, lokalt och inget konto.","intro":"Beräkna kinetisk energi från massa och hastighet, gravitationell potentiell energi från höjd, eller lös hastighet från en känd kinetisk energi. \nVälj nollhöjdsreferens och gravitation som används för uppskattningen.","howQuestion":"Hur beräknar man kinetisk energi?","howAnswer":"Kinetisk energi är hälften av massa gånger hastighet i kvadrat: KE = ½mv². \nGravitationspotentialenergin i förhållande till en vald höjd är PE = mgh. \nTill exempel har ett 2 kg föremål som rör sig med 3 m/s 9 J kinetisk energi. \nSumman som visas är summan av dessa idealiserade värden, inte en förutsägelse som inkluderar friktion eller andra förluster.","privacyQuestion":"Är mina värden uppladdade?","privacyAnswer":"Nej. Beräkningen körs lokalt i den här webbläsaren; \nvärdena laddas inte upp eller sparas.","fields":{"mode":"Beräkningsläge","energyMode":"Beräkna energi från hastighet","speedMode":"Lös hastighet från kinetisk energi","massKg":"Massa (kg)","velocityMps":"Hastighet (m/s)","kineticEnergyJ":"Kinetisk energi (J)","heightM":"Höjd över nollreferensen (m)","gravityMps2":"Gravitationsacceleration (m/s²)","accuracyNote":"Använd höjden i förhållande till din valda nollnivå. \nGravity är som standard 9.80665 m/s² men kan ändras. \nDenna idealiska uppskattning ignorerar friktion, luftmotstånd, rotation och relativistiska effekter; \ndet är inte en ingenjörs- eller säkerhetsbedömning."},"actions":{"calculate":"Beräkna energi","reset":"Återställ","copy":"Kopiera resultat","example":"Prova 2 kg vid 3 m/s","result":"Energiresultat"},"messages":{"calculated":"Beräkning klar.","checkInputs":"Ange en positiv massa och giltig hastighet eller kinetisk energi. \nHöjd kan vara negativ; \ngravitationen måste vara större än noll.","velocity":"Hastighet","kineticEnergy":"Kinetisk energi","potentialEnergy":"Gravitationsenergi","totalEnergy":"Total mekanisk energi"},"additionalFaqs":[{"question":"Kan jag hitta hastighet från kinetisk energi?","answer":"Ja. \nVälj \"Lös hastighet från kinetisk energi\" och ange sedan en positiv massa och ett kinetisk energivärde på noll eller högre. \nKalkylatorn använder v = √(2KE/m)."},{"question":"Varför kan potentiell energi vara negativ?","answer":"Potentiell energi mäts i förhållande till en referenshöjd som du väljer. \nEn position under den nollnivån har negativ mgh; \ndetta betyder inte att objektet har negativ massa eller att kinetisk energi är negativ."},{"question":"Inkluderar den totala mekaniska energin energiförluster?","answer":"Nej. Det är endast summan av kinetisk och gravitationell potentiell energi. \nFriktion, luftmotstånd, rotation, deformation och andra energiöverföringar modelleras inte."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"th":{"copyLanguage":"th","name":"เครื่องคำนวณพลังงานจลน์","title":"เครื่องคำนวณพลังงานจลน์ | UsefulVerse","description":"คำนวณพลังงานจลน์และพลังงานศักย์ หรือแก้ความเร็วจากพลังงาน \nฟรี ในพื้นที่และไม่มีบัญชี","intro":"คำนวณพลังงานจลน์จากมวลและความเร็ว พลังงานศักย์โน้มถ่วงจากความสูง หรือแก้ความเร็วจากพลังงานจลน์ที่ทราบ \nChoose the zero-height reference and gravity used for the estimate.","howQuestion":"How do you calculate kinetic energy?","howAnswer":"Kinetic energy is one half of mass times speed squared: KE = ½mv². \nพลังงานศักย์โน้มถ่วงที่สัมพันธ์กับความสูงที่เลือกคือ PE = mgh \nตัวอย่างเช่น วัตถุหนัก 2 กิโลกรัมซึ่งเคลื่อนที่ด้วยความเร็ว 3 เมตร/วินาที มีพลังงานจลน์ 9 J \nผลรวมที่แสดงคือผลรวมของค่าในอุดมคติเหล่านี้ ไม่ใช่การคาดการณ์ที่รวมแรงเสียดทานหรือการสูญเสียอื่นๆ","privacyQuestion":"มีการอัปโหลดค่าของฉันหรือไม่","privacyAnswer":"ไม่ การคำนวณทำงานภายในเบราว์เซอร์นี้ \nค่าจะไม่ถูกอัพโหลดหรือบันทึก","fields":{"mode":"โหมดการคำนวณ","energyMode":"คำนวณพลังงานจากความเร็ว","speedMode":"แก้ความเร็วจากพลังงานจลน์","massKg":"มวล (กก.)","velocityMps":"ความเร็ว (เมตร/วินาที)","kineticEnergyJ":"พลังงานจลน์ (เจ)","heightM":"ความสูงเหนือการอ้างอิงศูนย์ (ม.)","gravityMps2":"ความเร่งโน้มถ่วง (m/s²)","accuracyNote":"ใช้ความสูงสัมพันธ์กับระดับศูนย์ที่คุณเลือก \nแรงโน้มถ่วงมีค่าเริ่มต้นเป็น 9.80665 m/s² แต่สามารถเปลี่ยนแปลงได้ \nการประมาณค่าในอุดมคตินี้ละเว้นผลกระทบจากแรงเสียดทาน แรงต้านอากาศ การหมุน และผลกระทบเชิงสัมพัทธภาพ \nไม่ใช่การประเมินทางวิศวกรรมหรือความปลอดภัย"},"actions":{"calculate":"คำนวณพลังงาน","reset":"รีเซ็ต","copy":"ผลการคัดลอก","example":"ลอง 2 กก. ที่ 3 เมตร/วินาที","result":"ผลลัพธ์ด้านพลังงาน"},"messages":{"calculated":"คำนวณพร้อม","checkInputs":"ป้อนมวลบวกและความเร็วหรือพลังงานจลน์ที่ถูกต้อง \nความสูงอาจเป็นลบ \nแรงโน้มถ่วงจะต้องมากกว่าศูนย์","velocity":"ความเร็ว","kineticEnergy":"พลังงานจลน์","potentialEnergy":"พลังงานศักย์โน้มถ่วง","totalEnergy":"พลังงานกลทั้งหมด"},"additionalFaqs":[{"question":"หาความเร็วจากพลังงานจลน์ได้ไหม","answer":"ใช่. \nเลือก “แก้ความเร็วจากพลังงานจลน์” จากนั้นป้อนมวลบวกและค่าพลังงานจลน์เป็นศูนย์หรือมากกว่า \nเครื่องคิดเลขใช้ v = √(2KE/m)"},{"question":"เหตุใดพลังงานศักย์จึงเป็นลบได้","answer":"พลังงานศักย์วัดโดยสัมพันธ์กับความสูงอ้างอิงที่คุณเลือก \nตำแหน่งที่ต่ำกว่าระดับศูนย์นั้นมี mgh ติดลบ \nนี่ไม่ได้หมายความว่าวัตถุนั้นมีมวลลบหรือพลังงานจลน์เป็นลบ"},{"question":"พลังงานกลทั้งหมดรวมการสูญเสียพลังงานหรือไม่","answer":"ไม่ใช่ เป็นผลรวมของพลังงานศักย์จลน์และแรงโน้มถ่วงเท่านั้น \nแรงเสียดทาน แรงต้านอากาศ การหมุน การเสียรูป และการถ่ายโอนพลังงานอื่นๆ ไม่ได้เป็นแบบจำลอง"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"uk":{"copyLanguage":"uk","name":"Калькулятор кінетичної енергії","title":"Калькулятор кінетичної енергії | UsefulVerse","description":"Обчисліть кінетичну та потенційну енергію або розв’яжіть швидкість за допомогою енергії. \nБезкоштовний, локальний і без облікового запису.","intro":"Обчисліть кінетичну енергію за масою та швидкістю, гравітаційну потенційну енергію за висотою або розв’яжіть швидкість за відомою кінетичною енергією. \nВиберіть нульову висоту та силу тяжіння, які використовуються для оцінки.","howQuestion":"Як обчислити кінетичну енергію?","howAnswer":"Кінетична енергія дорівнює половині маси, помноженої на швидкість у квадраті: KE = ½mv². \nГравітаційна потенціальна енергія відносно вибраної висоти дорівнює PE = mgh. \nНаприклад, об’єкт масою 2 кг, який рухається зі швидкістю 3 м/с, має кінетичну енергію 9 Дж. \nПоказана загальна сума є сумою цих ідеалізованих значень, а не прогнозом, який включає тертя чи інші втрати.","privacyQuestion":"Чи завантажено мої значення?","privacyAnswer":"Ні. Обчислення виконується локально в цьому браузері; \nзначення не завантажуються і не зберігаються.","fields":{"mode":"Режим розрахунку","energyMode":"Обчислити енергію за швидкістю","speedMode":"Розв’яжіть швидкість, виходячи з кінетичної енергії","massKg":"Маса (кг)","velocityMps":"Швидкість (м/с)","kineticEnergyJ":"Кінетична енергія (Дж)","heightM":"Висота над нульовою точкою (м)","gravityMps2":"Гравітаційне прискорення (м/с²)","accuracyNote":"Використовуйте висоту відносно вибраного нульового рівня. \nГравітація за замовчуванням 9.80665 m/s², але її можна змінити. \nЦя ідеальна оцінка ігнорує тертя, опір повітря, обертання та релятивістські ефекти; \nце не інженерна оцінка чи оцінка безпеки."},"actions":{"calculate":"Обчисліть енергію","reset":"Скинути","copy":"Результат копіювання","example":"Спробуйте 2 кг при 3 м/с","result":"Енергетичний результат"},"messages":{"calculated":"Розрахунок готовий.","checkInputs":"Введіть позитивну масу та дійсну швидкість або кінетичну енергію. \nВисота може бути негативною; \nсила тяжіння повинна бути більше нуля.","velocity":"Швидкість","kineticEnergy":"Кінетична енергія","potentialEnergy":"Гравітаційна потенційна енергія","totalEnergy":"Повна механічна енергія"},"additionalFaqs":[{"question":"Чи можу я знайти швидкість за допомогою кінетичної енергії?","answer":"Так. \nВиберіть «Визначити швидкість із кінетичної енергії», а потім введіть додатну масу та значення кінетичної енергії, що дорівнює нулю або більше. \nКалькулятор використовує v = √(2KE/m)."},{"question":"Чому потенційна енергія може бути від’ємною?","answer":"Потенціальна енергія вимірюється відносно заданої висоти, яку ви вибираєте. \nПозиція нижче нульового рівня має від’ємний mgh; \nце не означає, що об’єкт має від’ємну масу або що кінетична енергія від’ємна."},{"question":"Чи включає повна механічна енергія втрати енергії?","answer":"Ні. Це лише сума кінетичної та гравітаційної потенційної енергії. \nТертя, опір повітря, обертання, деформація та інші передачі енергії не моделюються."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"sw":{"copyLanguage":"sw","name":"Kikokotoo cha Nishati ya Kinetic","title":"Kikokotoo cha Nishati ya Kinetic | UsefulVerse","description":"Kokotoa nishati ya kinetiki na inayoweza kutokea au suluhisha kasi kutoka kwa nishati. \nBure, ndani na hakuna akaunti.","intro":"Kokotoa nishati ya kinetiki kutoka kwa wingi na kasi, nishati ya uvutano inayoweza kutokea kutoka kwa urefu, au suluhisha kasi kutoka kwa nishati inayojulikana ya kinetiki. \nChagua marejeleo ya urefu wa sifuri na mvuto unaotumika kwa makadirio.","howQuestion":"Je, unahesabuje nishati ya kinetic?","howAnswer":"Nishati ya kinetiki ni nusu moja ya kasi ya mara misa yenye mraba: KE = ½mv². \nNishati inayowezekana ya uvutano inayohusiana na urefu uliochaguliwa ni PE = mgh. \nKwa mfano, kitu cha kilo 2 kinachotembea kwa 3 m / s kina 9 J ya nishati ya kinetic. \nJumla iliyoonyeshwa ni jumla ya thamani hizi zilizoboreshwa, si utabiri unaojumuisha msuguano au hasara nyinginezo.","privacyQuestion":"Je, thamani zangu zimepakiwa?","privacyAnswer":"No. Hesabu inaendeshwa ndani ya kivinjari hiki; \nmaadili hayajapakiwa au kuhifadhiwa.","fields":{"mode":"Njia ya kuhesabu","energyMode":"Kokotoa nishati kutoka kwa kasi","speedMode":"Tatua kasi kutoka kwa nishati ya kinetic","massKg":"Misa (kg)","velocityMps":"Kasi (m/s)","kineticEnergyJ":"Nishati ya Kinetiki (J)","heightM":"Urefu juu ya marejeleo sufuri (m)","gravityMps2":"Kasi ya uvutano (m/s²)","accuracyNote":"Tumia urefu kulingana na kiwango cha sifuri ulichochagua. \nMvuto chaguomsingi kuwa 9.80665 m/s² lakini inaweza kubadilishwa. \nMakadirio haya bora hupuuza msuguano, upinzani wa hewa, mzunguko na athari za relativist; \nsio tathmini ya uhandisi au usalama."},"actions":{"calculate":"Kokotoa nishati","reset":"Weka upya","copy":"Nakili matokeo","example":"Jaribu kilo 2 kwa 3 m / s","result":"Matokeo ya nishati"},"messages":{"calculated":"Hesabu tayari.","checkInputs":"Weka misa chanya na kasi halali au nishati ya kinetiki. \nUrefu unaweza kuwa mbaya; \nmvuto lazima uwe mkubwa kuliko sufuri.","velocity":"Kasi","kineticEnergy":"Nishati ya kinetiki","potentialEnergy":"Nishati inayowezekana ya mvuto","totalEnergy":"Jumla ya nishati ya mitambo"},"additionalFaqs":[{"question":"Je, ninaweza kupata kasi kutoka kwa nishati ya kinetic?","answer":"Ndiyo. \nChagua \"Tatua kasi kutoka kwa nishati ya kinetiki,\" kisha uweke misa chanya na thamani ya nishati ya kinetiki ya sifuri au zaidi. \nCalculator hutumia v = √(2KE/m)."},{"question":"Kwa nini nishati inayowezekana inaweza kuwa hasi?","answer":"Nishati inayowezekana hupimwa kulingana na urefu wa marejeleo unaochagua. \nNafasi iliyo chini ya kiwango cha sifuri ina mgh hasi; \nhii haimaanishi kuwa kitu kina misa hasi au nishati ya kinetic ni hasi."},{"question":"Je, jumla ya nishati ya mitambo inajumuisha hasara za nishati?","answer":"Nambari ni jumla ya nishati inayoweza kutokea ya kinetic na mvuto pekee. \nMsuguano, upinzani wa hewa, mzunguko, deformation na uhamisho mwingine wa nishati sio mfano."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"mr":{"copyLanguage":"mr","name":"कायनेटिक एनर्जी कॅल्क्युलेटर","title":"कायनेटिक एनर्जी कॅल्क्युलेटर | UsefulVerse","description":"गतिज आणि संभाव्य ऊर्जेची गणना करा किंवा ऊर्जेपासून गती सोडवा. \nविनामूल्य, स्थानिक आणि कोणतेही खाते नाही.","intro":"वस्तुमान आणि गती, उंचीवरून गुरुत्वाकर्षण संभाव्य ऊर्जा, किंवा ज्ञात गतीज उर्जेपासून गतीचे निराकरण करा. \nअंदाजासाठी वापरलेले शून्य-उंची संदर्भ आणि गुरुत्वाकर्षण निवडा.","howQuestion":"तुम्ही गतिज उर्जेची गणना कशी करता?","howAnswer":"गतिज ऊर्जा म्हणजे वस्तुमान गुणाकार गती वर्गाच्या अर्धा: KE = ½mv². \nनिवडलेल्या उंचीच्या सापेक्ष गुरुत्वीय संभाव्य ऊर्जा PE = mgh आहे. \nउदाहरणार्थ, 3 m/s वेगाने फिरणाऱ्या 2 किलोच्या वस्तूमध्ये 9 J गतीज ऊर्जा असते. \nदाखवलेली एकूण ही या आदर्श मूल्यांची बेरीज आहे, घर्षण किंवा इतर नुकसानांचा समावेश असलेला अंदाज नाही.","privacyQuestion":"माझी मूल्ये अपलोड केली आहेत का?","privacyAnswer":"क्र. गणना या ब्राउझरमध्ये स्थानिक पातळीवर चालते; \nमूल्ये अपलोड किंवा जतन केलेली नाहीत.","fields":{"mode":"गणना मोड","energyMode":"गतीवरून ऊर्जेची गणना करा","speedMode":"गतीज ऊर्जेपासून वेग सोडवा","massKg":"वस्तुमान (किलो)\n\n९८७६५४००१२४५६७८९ वेग (मी/से)\n\n९८७६५४००१३४५६७८९ गतिज ऊर्जा (जे)","velocityMps":"गती (m/s)","kineticEnergyJ":"गतिज ऊर्जा (J)","heightM":"शून्य संदर्भातील उंची (मी)","gravityMps2":"गुरुत्वीय प्रवेग (m/s²)","accuracyNote":"तुम्ही निवडलेल्या शून्य पातळीशी संबंधित उंची वापरा. \nगुरुत्वाकर्षण डीफॉल्ट 9.80665 m/s² वर आहे परंतु बदलले जाऊ शकते. \nहा आदर्श अंदाज घर्षण, हवेचा प्रतिकार, रोटेशन आणि सापेक्षतावादी प्रभावांकडे दुर्लक्ष करतो; \nहे अभियांत्रिकी किंवा सुरक्षा मूल्यांकन नाही."},"actions":{"calculate":"ऊर्जेची गणना करा","reset":"रीसेट करा","copy":"निकाल कॉपी करा","example":"3 m/s वर 2 kg वापरून पहा","result":"ऊर्जा निकाल"},"messages":{"calculated":"गणना तयार आहे.","checkInputs":"सकारात्मक वस्तुमान आणि वैध गती किंवा गतीज ऊर्जा प्रविष्ट करा. \nउंची नकारात्मक असू शकते; \nगुरुत्वाकर्षण शून्यापेक्षा जास्त असावे.","velocity":"वेग","kineticEnergy":"गतिज ऊर्जा","potentialEnergy":"गुरुत्वाकर्षण संभाव्य ऊर्जा","totalEnergy":"एकूण यांत्रिक ऊर्जा"},"additionalFaqs":[{"question":"मी गतिज उर्जेपासून वेग शोधू शकतो का?","answer":"होय. \n\"गतिज उर्जेपासून गती सोडवा\" निवडा, नंतर सकारात्मक वस्तुमान आणि शून्य किंवा त्याहून अधिक गती-ऊर्जा मूल्य प्रविष्ट करा. \nकॅल्क्युलेटर v = √(2KE/m) वापरतो."},{"question":"संभाव्य ऊर्जा ऋण का असू शकते?","answer":"संभाव्य उर्जा तुम्ही निवडलेल्या संदर्भ उंचीच्या सापेक्ष मोजली जाते. \nशून्य पातळीच्या खाली असलेल्या स्थितीत नकारात्मक mgh आहे; \nयाचा अर्थ असा नाही की वस्तूचे वस्तुमान ऋण आहे किंवा गतिज ऊर्जा नकारात्मक आहे."},{"question":"एकूण यांत्रिक ऊर्जेमध्ये ऊर्जेच्या नुकसानीचा समावेश होतो का?","answer":"क्र. ही केवळ गतीज आणि गुरुत्वाकर्षण संभाव्य उर्जेची बेरीज आहे. \nघर्षण, वायु प्रतिरोध, रोटेशन, विकृतीकरण आणि इतर ऊर्जा हस्तांतरण मॉडेल केलेले नाहीत."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"te":{"copyLanguage":"te","name":"కైనెటిక్ ఎనర్జీ కాలిక్యులేటర్","title":"కైనెటిక్ ఎనర్జీ కాలిక్యులేటర్ | UsefulVerse","description":"గతి మరియు సంభావ్య శక్తిని లెక్కించండి లేదా శక్తి నుండి వేగాన్ని పరిష్కరించండి. \nఉచిత, స్థానిక మరియు ఖాతా లేదు.","intro":"ద్రవ్యరాశి మరియు వేగం నుండి గతి శక్తిని, ఎత్తు నుండి గురుత్వాకర్షణ సంభావ్య శక్తిని లెక్కించండి లేదా తెలిసిన గతి శక్తి నుండి వేగాన్ని పరిష్కరించండి. \nఅంచనా కోసం ఉపయోగించే సున్నా-ఎత్తు సూచన మరియు గురుత్వాకర్షణను ఎంచుకోండి.","howQuestion":"మీరు గతి శక్తిని ఎలా గణిస్తారు?","howAnswer":"గతి శక్తి స్క్వేర్డ్ మాస్ టైమ్స్ స్పీడ్‌లో సగం: KE = ½mv². \nఎంచుకున్న ఎత్తుకు సంబంధించి గురుత్వాకర్షణ సంభావ్య శక్తి PE = mgh. \nఉదాహరణకు, 3 m/s వద్ద కదిలే 2 కిలోల వస్తువు 9 J గతి శక్తిని కలిగి ఉంటుంది. \nచూపిన మొత్తం ఈ ఆదర్శీకరించిన విలువల మొత్తం, ఘర్షణ లేదా ఇతర నష్టాలను కలిగి ఉన్న అంచనా కాదు.","privacyQuestion":"నా విలువలు అప్‌లోడ్ చేయబడ్డాయా?","privacyAnswer":"సంఖ్య. ఈ బ్రౌజర్‌లో గణన స్థానికంగా నడుస్తుంది; \nవిలువలు అప్‌లోడ్ చేయబడవు లేదా సేవ్ చేయబడవు.","fields":{"mode":"గణన మోడ్","energyMode":"వేగం నుండి శక్తిని లెక్కించండి","speedMode":"గతి శక్తి నుండి వేగాన్ని పరిష్కరించండి","massKg":"మాస్ (కిలోలు)","velocityMps":"వేగం (మీ/సె)","kineticEnergyJ":"గతి శక్తి (J)","heightM":"సున్నా సూచన కంటే ఎత్తు (మీ)","gravityMps2":"గురుత్వాకర్షణ త్వరణం (m/s²)","accuracyNote":"మీరు ఎంచుకున్న సున్నా స్థాయికి సంబంధించి ఎత్తును ఉపయోగించండి. \nగ్రావిటీ 9.80665 m/s²కి డిఫాల్ట్ అవుతుంది కానీ మార్చవచ్చు. \nఈ ఆదర్శ అంచనా ఘర్షణ, గాలి నిరోధకత, భ్రమణం మరియు సాపేక్ష ప్రభావాలను విస్మరిస్తుంది; \nఇది ఇంజనీరింగ్ లేదా భద్రతా అంచనా కాదు."},"actions":{"calculate":"శక్తిని లెక్కించండి","reset":"రీసెట్ చేయండి","copy":"ఫలితాన్ని కాపీ చేయండి","example":"3 మీ/సె వద్ద 2 కిలోలు ప్రయత్నించండి","result":"శక్తి ఫలితం"},"messages":{"calculated":"గణన సిద్ధంగా ఉంది.","checkInputs":"సానుకూల ద్రవ్యరాశి మరియు చెల్లుబాటు అయ్యే వేగం లేదా గతి శక్తిని నమోదు చేయండి. \nఎత్తు ప్రతికూలంగా ఉండవచ్చు; \nగురుత్వాకర్షణ సున్నా కంటే ఎక్కువగా ఉండాలి.","velocity":"వేగం","kineticEnergy":"గతి శక్తి","potentialEnergy":"గురుత్వాకర్షణ సంభావ్య శక్తి","totalEnergy":"మొత్తం యాంత్రిక శక్తి"},"additionalFaqs":[{"question":"నేను గతి శక్తి నుండి వేగాన్ని కనుగొనగలనా?","answer":"అవును. \n\"కైనటిక్ ఎనర్జీ నుండి వేగాన్ని పరిష్కరించండి\"ని ఎంచుకుని, సానుకూల ద్రవ్యరాశిని మరియు సున్నా లేదా అంతకంటే ఎక్కువ గతి-శక్తి విలువను నమోదు చేయండి. \nకాలిక్యులేటర్ v = √(2KE/m)ని ఉపయోగిస్తుంది."},{"question":"సంభావ్య శక్తి ఎందుకు ప్రతికూలంగా ఉంటుంది?","answer":"మీరు ఎంచుకున్న రిఫరెన్స్ ఎత్తుకు సంబంధించి సంభావ్య శక్తి కొలుస్తారు. \nసున్నా స్థాయి కంటే దిగువన ఉన్న స్థానం ప్రతికూల mghని కలిగి ఉంటుంది; \nవస్తువు ప్రతికూల ద్రవ్యరాశిని కలిగి ఉందని లేదా గతి శక్తి ప్రతికూలంగా ఉందని దీని అర్థం కాదు."},{"question":"మొత్తం యాంత్రిక శక్తి శక్తి నష్టాలను కలిగి ఉందా?","answer":"సంఖ్య. ఇది గతి మరియు గురుత్వాకర్షణ సంభావ్య శక్తి యొక్క మొత్తం మాత్రమే. \nఘర్షణ, గాలి నిరోధకత, భ్రమణం, వైకల్యం మరియు ఇతర శక్తి బదిలీలు మోడల్ చేయబడవు."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ha":{"copyLanguage":"ha","name":"Kinetic Energy Calculator","title":"Kinetic Energy Calculator | UsefulVerse","description":"Lissafin motsin motsi da yuwuwar kuzari ko warware saurin makamashi. \nKyauta, gida kuma babu asusu.","intro":"Lissafin kuzarin motsa jiki daga taro da sauri, yuwuwar kuzarin nauyi daga tsayi, ko warware sauri daga sanannen kuzarin motsi. \nZaɓi nuni mai tsayi sifili da nauyi da aka yi amfani da shi don kimantawa.","howQuestion":"Ta yaya kuke lissafin kuzarin motsa jiki?","howAnswer":"Kinetic Energy shine rabin rabin yawan saurin murabba'i: KE = ½mv². \nƘarfin ƙarfin nauyi dangane da tsayin da aka zaɓa shine PE = mgh. \nMisali, abu mai nauyin kilogiram 2 yana motsi a 3 m/s yana da 9J na makamashin motsi. \nJimlar da aka nuna ita ce jimillar waɗannan kyawawan dabi'u, ba hasashe da ya haɗa da gogayya ko wasu asara ba.","privacyQuestion":"An loda kimara?","privacyAnswer":"A'a. Lissafin yana gudana a cikin gida a cikin wannan browser; \nba a ɗora darajar ko adana su ba.","fields":{"mode":"Yanayin Lissafi","energyMode":"Lissafin kuzari daga sauri","speedMode":"Warware sauri daga makamashin motsi","massKg":"Mass (kg)","velocityMps":"Gudun (m/s)","kineticEnergyJ":"Kinetic makamashi (J)","heightM":"Tsayi sama da sifiri (m)","gravityMps2":"Haɓakar nauyi (m/s²)","accuracyNote":"Yi amfani da tsayi dangane da matakin sifilin da kuka zaɓa. \nMatsakaicin nauyi zuwa 9.80665 m/s² amma ana iya canzawa. \nWannan maƙasudin ƙididdigewa yana watsi da gogayya, juriya na iska, jujjuyawa da sakamako masu alaƙa; \nba aikin injiniya ba ne ko kima na aminci."},"actions":{"calculate":"Yi lissafin makamashi","reset":"Sake saiti","copy":"Kwafi sakamakon","example":"Gwada 2 kg a 3 m/s","result":"Sakamakon makamashi"},"messages":{"calculated":"An shirya lissafin.","checkInputs":"Shigar da ingantacciyar taro da ingantacciyar sauri ko kuzarin motsi. \nTsayi na iya zama mara kyau; \nnauyi dole ne ya fi sifili.","velocity":"Sauri","kineticEnergy":"Kinetic makamashi","potentialEnergy":"Ƙarfin ƙarfin nauyi","totalEnergy":"Jimlar makamashin inji"},"additionalFaqs":[{"question":"Zan iya samun sauri daga makamashin motsi?","answer":"iya. \nZaɓi \"Maganin sauri daga makamashin motsi,\" sannan shigar da ingantaccen taro da ƙimar kuzarin sifili ko mafi girma. \nKalkuleta yana amfani da v = √(2KE/m)."},{"question":"Me yasa yuwuwar makamashi zai iya zama mara kyau?","answer":"Ana auna makamashi mai yuwuwa dangane da tsayin daka da ka zaba. \nMatsayin da ke ƙasa da matakin sifili yana da mgh mara kyau; \nwannan ba yana nufin abu yana da mummunan taro ba ko kuma kuzarin motsa jiki mara kyau ne."},{"question":"Shin jimillar makamashin inji ya haɗa da asarar makamashi?","answer":"A'a. Jimillar kuzarin motsa jiki da karfin nauyi ne kawai. \nRashin juriya, juriya, jujjuyawar iska, nakasawa da sauran abubuwan canja wurin makamashi ba a kera su ba."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"tl":{"copyLanguage":"tl","name":"Kinetic Energy Calculator","title":"Kinetic Energy Calculator | UsefulVerse","description":"Kalkulahin ang kinetic at potensyal na enerhiya o lutasin ang bilis mula sa enerhiya. \nLibre, lokal at walang account.","intro":"Kalkulahin ang kinetic energy mula sa masa at bilis, gravitational potential energy mula sa taas, o lutasin ang bilis mula sa isang kilalang kinetic energy. \nPiliin ang zero-height reference at gravity na ginamit para sa pagtatantya.","howQuestion":"Paano mo kinakalkula ang kinetic energy?","howAnswer":"Ang kinetic energy ay kalahati ng mass times speed squared: KE = ½mv². \nAng potensyal na enerhiya ng gravitational na nauugnay sa napiling taas ay PE = mgh. \nHalimbawa, ang isang 2 kg na bagay na gumagalaw sa 3 m/s ay may 9 J ng kinetic energy. \nAng kabuuang ipinakita ay ang kabuuan ng mga idealized na halagang ito, hindi isang hula na kinabibilangan ng friction o iba pang pagkalugi.","privacyQuestion":"Na-upload ba ang aking mga halaga?","privacyAnswer":"Hindi. Ang pagkalkula ay tumatakbo nang lokal sa browser na ito; \nang mga halaga ay hindi na-upload o nai-save.","fields":{"mode":"Mode ng pagkalkula","energyMode":"Kalkulahin ang enerhiya mula sa bilis","speedMode":"Lutasin ang bilis mula sa kinetic energy","massKg":"Mass (kg)","velocityMps":"Bilis (m/s)","kineticEnergyJ":"Kinetic energy (J)","heightM":"Taas sa itaas ng zero reference (m)","gravityMps2":"Gravitational acceleration (m/s²)","accuracyNote":"Gamitin ang taas na nauugnay sa iyong napiling zero level. \nNagde-default ang gravity sa 9.80665 m/s² ngunit maaaring baguhin. \nBinabalewala ng perpektong pagtatantya na ito ang friction, air resistance, rotation at relativistic effect; \nhindi ito isang engineering o safety assessment."},"actions":{"calculate":"Kalkulahin ang enerhiya","reset":"I-reset","copy":"Kopyahin ang resulta","example":"Subukan ang 2 kg sa 3 m/s","result":"Resulta ng enerhiya"},"messages":{"calculated":"Handa na ang pagkalkula.","checkInputs":"Maglagay ng positibong masa at wastong bilis o kinetic energy. \nMaaaring negatibo ang taas; \nang gravity ay dapat na mas malaki kaysa sa zero.","velocity":"Bilis","kineticEnergy":"Kinetic energy","potentialEnergy":"Gravitational potensyal na enerhiya","totalEnergy":"Kabuuang mekanikal na enerhiya"},"additionalFaqs":[{"question":"Maaari ba akong makahanap ng bilis mula sa kinetic energy?","answer":"Oo. \nPiliin ang \"Solve speed from kinetic energy,\" pagkatapos ay maglagay ng positive mass at isang kinetic-energy value na zero o mas mataas. \nAng calculator ay gumagamit ng v = √(2KE/m)."},{"question":"Bakit maaaring negatibo ang potensyal na enerhiya?","answer":"Ang potensyal na enerhiya ay sinusukat kaugnay ng isang reference na taas na pipiliin mo. \nAng isang posisyon sa ibaba ng zero na antas ay may negatibong mgh; \nhindi ito nangangahulugan na ang bagay ay may negatibong masa o ang kinetic energy ay negatibo."},{"question":"Kasama ba sa kabuuang mekanikal na enerhiya ang mga pagkawala ng enerhiya?","answer":"Hindi. Ito ay kabuuan ng kinetic at gravitational potential energy lamang. \nAng friction, air resistance, rotation, deformation at iba pang energy transfers ay hindi namodelo."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"ta":{"copyLanguage":"ta","name":"இயக்க ஆற்றல் கால்குலேட்டர்","title":"இயக்க ஆற்றல் கால்குலேட்டர் | UsefulVerse","description":"இயக்கவியல் மற்றும் சாத்தியமான ஆற்றலைக் கணக்கிடுங்கள் அல்லது ஆற்றலில் இருந்து வேகத்தைத் தீர்க்கவும். \nஇலவசம், உள்ளூர் மற்றும் கணக்கு இல்லை.","intro":"நிறை மற்றும் வேகத்திலிருந்து இயக்க ஆற்றலைக் கணக்கிடவும், உயரத்திலிருந்து ஈர்ப்பு ஆற்றல் ஆற்றலைக் கணக்கிடவும் அல்லது அறியப்பட்ட இயக்க ஆற்றலில் இருந்து வேகத்தைத் தீர்க்கவும். \nமதிப்பீட்டிற்குப் பயன்படுத்தப்படும் பூஜ்ஜிய உயரக் குறிப்பு மற்றும் ஈர்ப்பு விசையைத் தேர்வு செய்யவும்.","howQuestion":"இயக்க ஆற்றலை எவ்வாறு கணக்கிடுவது?","howAnswer":"இயக்க ஆற்றல் என்பது வெகுஜன மடங்கு வேகத்தின் ஒரு பாதி ஸ்கொயர்: KE = ½mv². \nதேர்ந்தெடுக்கப்பட்ட உயரத்துடன் தொடர்புடைய ஈர்ப்பு ஆற்றல் PE = mgh ஆகும். \nஎடுத்துக்காட்டாக, 3 மீ/வி வேகத்தில் நகரும் 2 கிலோ பொருள் 9 ஜே இயக்க ஆற்றலைக் கொண்டுள்ளது. \nகாட்டப்படும் மொத்தமானது இந்த இலட்சியப்படுத்தப்பட்ட மதிப்புகளின் கூட்டுத்தொகையாகும், உராய்வு அல்லது பிற இழப்புகளை உள்ளடக்கிய கணிப்பு அல்ல.","privacyQuestion":"எனது மதிப்புகள் பதிவேற்றப்பட்டதா?","privacyAnswer":"எண். கணக்கீடு இந்த உலாவியில் உள்நாட்டில் இயங்குகிறது; \nமதிப்புகள் பதிவேற்றப்படவில்லை அல்லது சேமிக்கப்படவில்லை.","fields":{"mode":"கணக்கீட்டு முறை","energyMode":"வேகத்திலிருந்து ஆற்றலைக் கணக்கிடுங்கள்","speedMode":"இயக்க ஆற்றலில் இருந்து வேகத்தைத் தீர்க்கவும்","massKg":"நிறை (கிலோ)","velocityMps":"வேகம் (மீ/வி)","kineticEnergyJ":"இயக்க ஆற்றல் (J)","heightM":"பூஜ்ஜிய குறிப்புக்கு மேல் உயரம் (மீ)","gravityMps2":"ஈர்ப்பு முடுக்கம் (m/s²)","accuracyNote":"நீங்கள் தேர்ந்தெடுத்த பூஜ்ஜிய நிலைக்கு தொடர்புடைய உயரத்தைப் பயன்படுத்தவும். \nபுவியீர்ப்பு இயல்புநிலை 9.80665 m/s² க்கு ஆனால் மாற்றப்படலாம். \nஇந்த சிறந்த மதிப்பீடு உராய்வு, காற்று எதிர்ப்பு, சுழற்சி மற்றும் சார்பியல் விளைவுகளை புறக்கணிக்கிறது; \nஇது ஒரு பொறியியல் அல்லது பாதுகாப்பு மதிப்பீடு அல்ல."},"actions":{"calculate":"ஆற்றலைக் கணக்கிடவும்","reset":"மீட்டமைக்கவும்","copy":"முடிவை நகலெடுக்கவும்","example":"3 மீ/வி வேகத்தில் 2 கிலோவை முயற்சிக்கவும்","result":"ஆற்றல் முடிவு"},"messages":{"calculated":"கணக்கீடு தயார்.","checkInputs":"நேர்மறை நிறை மற்றும் சரியான வேகம் அல்லது இயக்க ஆற்றலை உள்ளிடவும். \nஉயரம் எதிர்மறையாக இருக்கலாம்; \nஈர்ப்பு விசை பூஜ்ஜியத்தை விட அதிகமாக இருக்க வேண்டும்.","velocity":"வேகம்","kineticEnergy":"இயக்க ஆற்றல்","potentialEnergy":"ஈர்ப்பு திறன் ஆற்றல்","totalEnergy":"மொத்த இயந்திர ஆற்றல்"},"additionalFaqs":[{"question":"இயக்க ஆற்றலில் இருந்து வேகத்தைக் கண்டறிய முடியுமா?","answer":"ஆம். \n\"இயக்க ஆற்றலில் இருந்து வேகத்தைத் தீர்க்கவும்\" என்பதைத் தேர்ந்தெடுத்து, நேர்மறை நிறை மற்றும் இயக்க ஆற்றல் மதிப்பு பூஜ்ஜியம் அல்லது அதற்கு மேல் உள்ளிடவும். \nகால்குலேட்டர் v = √(2KE/m) ஐப் பயன்படுத்துகிறது."},{"question":"ஆற்றல் ஏன் எதிர்மறையாக இருக்கலாம்?","answer":"நீங்கள் தேர்ந்தெடுக்கும் குறிப்பு உயரத்துடன் தொடர்புடைய ஆற்றல் அளவிடப்படுகிறது. \nஅந்த பூஜ்ஜிய நிலைக்கு கீழே ஒரு நிலை எதிர்மறை mgh உள்ளது; \nபொருள் எதிர்மறை நிறை அல்லது இயக்க ஆற்றல் எதிர்மறை என்று அர்த்தம் இல்லை."},{"question":"மொத்த இயந்திர ஆற்றலில் ஆற்றல் இழப்புகள் உள்ளதா?","answer":"எண். இது இயக்கவியல் மற்றும் ஈர்ப்பு ஆற்றல் ஆற்றல்களின் கூட்டுத்தொகை மட்டுமே. \nஉராய்வு, காற்று எதிர்ப்பு, சுழற்சி, உருமாற்றம் மற்றும் பிற ஆற்றல் பரிமாற்றங்கள் மாதிரியாக இல்லை."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"fa":{"copyLanguage":"fa","name":"ماشین حساب انرژی جنبشی","title":"ماشین حساب انرژی جنبشی | UsefulVerse","description":"انرژی جنبشی و پتانسیل را محاسبه کنید یا سرعت را از انرژی حل کنید. \nرایگان، محلی و بدون حساب.","intro":"محاسبه انرژی جنبشی از جرم و سرعت، انرژی پتانسیل گرانشی از ارتفاع، یا حل سرعت از انرژی جنبشی شناخته شده. \nمرجع ارتفاع صفر و گرانش مورد استفاده برای برآورد را انتخاب کنید.","howQuestion":"چگونه انرژی جنبشی را محاسبه می کنید؟","howAnswer":"انرژی جنبشی نصف جرم ضربدر سرعت مجذور است: KE = ½mv². \nانرژی پتانسیل گرانشی نسبت به ارتفاع انتخاب شده PE = mgh است. \nبه عنوان مثال، جسم 2 کیلوگرمی که با سرعت 3 متر بر ثانیه حرکت می کند، 9 ژول انرژی جنبشی دارد. \nمجموع نشان داده شده مجموع این مقادیر ایده آل است، نه پیش بینی ای که شامل اصطکاک یا سایر تلفات باشد.","privacyQuestion":"آیا مقادیر من آپلود شده اند؟","privacyAnswer":"نه. محاسبه به صورت محلی در این مرورگر انجام می شود. \nمقادیر آپلود یا ذخیره نمی شوند.","fields":{"mode":"حالت محاسبه","energyMode":"محاسبه انرژی از سرعت","speedMode":"حل سرعت از انرژی جنبشی","massKg":"جرم (کیلوگرم)","velocityMps":"سرعت (m/s)","kineticEnergyJ":"انرژی جنبشی (J)","heightM":"ارتفاع بالاتر از مرجع صفر (متر)","gravityMps2":"شتاب گرانشی (m/s²)","accuracyNote":"از ارتفاع نسبت به سطح صفر انتخابی خود استفاده کنید. \nGravity روی 9.80665 m/s² پیش‌فرض است اما می‌توان آن را تغییر داد. \nاین تخمین ایده آل اصطکاک، مقاومت هوا، چرخش و اثرات نسبیتی را نادیده می گیرد. \nاین یک ارزیابی مهندسی یا ایمنی نیست."},"actions":{"calculate":"محاسبه انرژی","reset":"تنظیم مجدد","copy":"نتیجه را کپی کنید","example":"2 کیلوگرم را با سرعت 3 متر بر ثانیه امتحان کنید","result":"نتیجه انرژی"},"messages":{"calculated":"محاسبه آماده.","checkInputs":"جرم مثبت و سرعت معتبر یا انرژی جنبشی را وارد کنید. \nقد ممکن است منفی باشد. \nگرانش باید بزرگتر از صفر باشد.","velocity":"سرعت","kineticEnergy":"انرژی جنبشی","potentialEnergy":"انرژی پتانسیل گرانشی","totalEnergy":"انرژی مکانیکی کل"},"additionalFaqs":[{"question":"آیا می توانم سرعت را از انرژی جنبشی پیدا کنم؟","answer":"بله. \n«حل سرعت از انرژی جنبشی» را انتخاب کنید، سپس جرم مثبت و مقدار انرژی جنبشی صفر یا بیشتر را وارد کنید. \nماشین حساب از v = √(2KE/m) استفاده می کند."},{"question":"چرا انرژی پتانسیل می تواند منفی باشد؟","answer":"انرژی بالقوه نسبت به ارتفاع مرجعی که انتخاب می کنید اندازه گیری می شود. \nموقعیتی که زیر آن سطح صفر است، mgh منفی دارد. \nاین بدان معنا نیست که جسم جرم منفی دارد یا انرژی جنبشی منفی است."},{"question":"آیا کل انرژی مکانیکی شامل تلفات انرژی می شود؟","answer":"شماره فقط حاصل جمع انرژی پتانسیل جنبشی و گرانشی است. \nاصطکاک، مقاومت هوا، چرخش، تغییر شکل و سایر انتقال انرژی مدل سازی نشده است."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"am":{"copyLanguage":"am","name":"Kinetic Energy Calculator","title":"Kinetic Energy Calculator | UsefulVerse","description":"የእንቅስቃሴ እና እምቅ ጉልበት አስላ ወይም ከኃይል ፍጥነትን መፍታት። \nነፃ፣ አካባቢያዊ እና ምንም መለያ የለም።","intro":"የኪነቲክ ሃይልን ከጅምላ እና ፍጥነት ያሰሉ፣ ከቁመት የስበት ኃይልን ያስሉ ወይም ከሚታወቅ የኪነቲክ ሃይል ፍጥነትን ይፍቱ። \nለግምቱ ጥቅም ላይ የዋለውን የዜሮ ቁመት ማጣቀሻ እና ስበት ይምረጡ።","howQuestion":"የኪነቲክ ሃይልን እንዴት ያስሉታል?","howAnswer":"Kinetic energy የጅምላ ጊዜ የፍጥነት መጠን አንድ ግማሽ ነው፡ KE = ½mv²። \nከተመረጠው ቁመት አንጻር የስበት ኃይል እምቅ ኃይል PE = mgh ነው። \nለምሳሌ 2 ኪሎ ግራም በ 3 ሜትር / ሰ የሚንቀሳቀስ ነገር 9 ጂ የኪነቲክ ሃይል አለው. \nየሚታየው አጠቃላይ የነዚህ ሃሳባዊ እሴቶች ድምር ነው እንጂ ግጭትን ወይም ሌሎች ኪሳራዎችን የሚያካትት ትንበያ አይደለም።","privacyQuestion":"እሴቶቼ ተሰቅለዋል?","privacyAnswer":"ቁጥር በዚህ አሳሽ ውስጥ ስሌቱ በአካባቢው ይሰራል; \nእሴቶቹ አልተሰቀሉም ወይም አልተቀመጡም.","fields":{"mode":"ስሌት ሁነታ","energyMode":"ኃይልን ከፍጥነት አስላ","speedMode":"ከኪነቲክ ሃይል ፍጥነትን ይፍቱ","massKg":"ቅዳሴ (ኪግ)","velocityMps":"ፍጥነት (ሜ/ሰ)","kineticEnergyJ":"Kinetic energy (ጄ)","heightM":"ከፍታ ከዜሮ ማጣቀሻ (ሜ) በላይ","gravityMps2":"የስበት ማጣደፍ (ሜ/ሰ²)","accuracyNote":"ከመረጡት የዜሮ ደረጃ አንጻር ቁመትን ይጠቀሙ። \nየስበት ኃይል ነባሪዎች ወደ 9.80665 m/s² ነው ነገር ግን ሊቀየር ይችላል። \nይህ ተስማሚ ግምት ሰበቃ, የአየር መቋቋም, ማሽከርከር እና አንጻራዊ ውጤቶች ችላ; \nየምህንድስና ወይም የደህንነት ግምገማ አይደለም."},"actions":{"calculate":"ጉልበት አስላ","reset":"ዳግም አስጀምር","copy":"ውጤት ቅዳ","example":"2 ኪሎ ግራም በ 3 ሜትር / ሰ","result":"የኢነርጂ ውጤት"},"messages":{"calculated":"ስሌት ዝግጁ ነው።","checkInputs":"አዎንታዊ የጅምላ እና ትክክለኛ ፍጥነት ወይም የእንቅስቃሴ ጉልበት ያስገቡ። \nቁመት አሉታዊ ሊሆን ይችላል; \nየስበት ኃይል ከዜሮ በላይ መሆን አለበት.","velocity":"ፍጥነት","kineticEnergy":"Kinetic energy","potentialEnergy":"የስበት ኃይል","totalEnergy":"ጠቅላላ የሜካኒካል ኃይል"},"additionalFaqs":[{"question":"ከኪነቲክ ሃይል ፍጥነት ማግኘት እችላለሁን?","answer":"አዎ። \n“ፍጥነትን ከኪነቲክ ኢነርጂ ይፍቱ” ን ይምረጡ፣ ከዚያ አወንታዊ ክብደት እና ዜሮ ወይም ከዚያ በላይ የሆነ የኪነቲክ-ኢነርጂ እሴት ያስገቡ። \nካልኩሌተሩ v = √(2KE/m) ይጠቀማል።"},{"question":"እምቅ ኃይል ለምን አሉታዊ ሊሆን ይችላል?","answer":"እምቅ ኃይል የሚለካው እርስዎ ከመረጡት የማጣቀሻ ቁመት አንጻር ነው። \nከዜሮ ደረጃ በታች ያለው ቦታ አሉታዊ mgh; \nይህ ማለት እቃው አሉታዊ ክብደት አለው ወይም የእንቅስቃሴ ጉልበት አሉታዊ ነው ማለት አይደለም."},{"question":"አጠቃላይ የሜካኒካል ኃይል የኃይል ኪሳራዎችን ያጠቃልላል?","answer":"አይደለም የኪነቲክ እና የስበት ኃይል ድምር ብቻ ነው። \nግጭት, የአየር መቋቋም, ማዞር, መበላሸት እና ሌሎች የኃይል ማስተላለፊያዎች ሞዴል አይደሉም."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"},"gu":{"copyLanguage":"gu","name":"કાઇનેટિક એનર્જી કેલ્ક્યુલેટર","title":"કાઇનેટિક એનર્જી કેલ્ક્યુલેટર | UsefulVerse","description":"ગતિ અને સંભવિત ઊર્જાની ગણતરી કરો અથવા ઊર્જામાંથી ઝડપ ઉકેલો. \nમફત, સ્થાનિક અને કોઈ ખાતું નથી.","intro":"દળ અને ગતિમાંથી ગતિ ઊર્જા, ઊંચાઈમાંથી ગુરુત્વાકર્ષણ સંભવિત ઊર્જાની ગણતરી કરો અથવા જાણીતી ગતિ ઊર્જામાંથી ઝડપ ઉકેલો. \nઅંદાજ માટે વપરાયેલ શૂન્ય-ઊંચાઈ સંદર્ભ અને ગુરુત્વાકર્ષણ પસંદ કરો.","howQuestion":"તમે ગતિ ઊર્જાની ગણતરી કેવી રીતે કરશો?","howAnswer":"ગતિ ઉર્જા એ સામૂહિક ગણી ઝડપ સ્ક્વેરનો અડધો ભાગ છે: KE = ½mv². \nપસંદ કરેલી ઊંચાઈની તુલનામાં ગુરુત્વાકર્ષણ સંભવિત ઊર્જા PE = mgh છે. \nઉદાહરણ તરીકે, 3 મીટર/સેકન્ડની ઝડપે ગતિ કરતી 2 કિલોની વસ્તુમાં 9 J ગતિ ઊર્જા હોય છે. \nદર્શાવેલ કુલ આ આદર્શ મૂલ્યોનો સરવાળો છે, ઘર્ષણ અથવા અન્ય નુકસાનનો સમાવેશ કરતું અનુમાન નથી.","privacyQuestion":"શું મારા મૂલ્યો અપલોડ થયા છે?","privacyAnswer":"નંબર. ગણતરી આ બ્રાઉઝરમાં સ્થાનિક રીતે ચાલે છે; \nમૂલ્યો અપલોડ અથવા સાચવેલ નથી.","fields":{"mode":"ગણતરી મોડ","energyMode":"ઝડપ થી ઊર્જાની ગણતરી કરો","speedMode":"ગતિ ઊર્જામાંથી ઝડપ ઉકેલો","massKg":"માસ (કિલો)","velocityMps":"ઝડપ (m/s)","kineticEnergyJ":"ગતિ ઊર્જા (J)","heightM":"શૂન્ય સંદર્ભ (m) ઉપરની ઊંચાઈ","gravityMps2":"ગુરુત્વાકર્ષણ પ્રવેગક (m/s²)","accuracyNote":"તમારા પસંદ કરેલા શૂન્ય સ્તરને સંબંધિત ઊંચાઈનો ઉપયોગ કરો. \nગુરુત્વાકર્ષણ ડિફોલ્ટ 9.80665 m/s² પર છે પરંતુ બદલી શકાય છે. \nઆ આદર્શ અંદાજ ઘર્ષણ, હવા પ્રતિકાર, પરિભ્રમણ અને સાપેક્ષ અસરોને અવગણે છે; \nતે એન્જિનિયરિંગ અથવા સલામતી મૂલ્યાંકન નથી."},"actions":{"calculate":"ઊર્જાની ગણતરી કરો","reset":"રીસેટ કરો","copy":"પરિણામની નકલ કરો","example":"3 m/s પર 2 kg અજમાવો","result":"ઉર્જા પરિણામ"},"messages":{"calculated":"ગણતરી તૈયાર.","checkInputs":"ધન સમૂહ અને માન્ય ગતિ અથવા ગતિ ઊર્જા દાખલ કરો. \nઊંચાઈ નકારાત્મક હોઈ શકે છે; \nગુરુત્વાકર્ષણ શૂન્ય કરતા વધારે હોવું જોઈએ.","velocity":"ઝડપ","kineticEnergy":"ગતિ ઊર્જા","potentialEnergy":"ગુરુત્વાકર્ષણ સંભવિત ઊર્જા","totalEnergy":"કુલ યાંત્રિક ઉર્જા"},"additionalFaqs":[{"question":"શું હું ગતિ ઊર્જામાંથી ઝડપ શોધી શકું?","answer":"હા. \n\"ગતિ ઊર્જામાંથી ઝડપ ઉકેલો\" પસંદ કરો, પછી હકારાત્મક સમૂહ અને શૂન્ય અથવા તેથી વધુનું ગતિ-ઊર્જા મૂલ્ય દાખલ કરો. \nકેલ્ક્યુલેટર v = √(2KE/m) નો ઉપયોગ કરે છે."},{"question":"સંભવિત ઉર્જા નકારાત્મક કેમ હોઈ શકે?","answer":"સંભવિત ઉર્જા તમે પસંદ કરો છો તે સંદર્ભ ઊંચાઈને અનુલક્ષીને માપવામાં આવે છે. \nશૂન્ય સ્તરથી નીચેની સ્થિતિ નકારાત્મક mgh ધરાવે છે; \nઆનો અર્થ એ નથી કે ઑબ્જેક્ટમાં નકારાત્મક દળ છે અથવા ગતિ ઊર્જા નકારાત્મક છે."},{"question":"શું કુલ યાંત્રિક ઉર્જામાં ઊર્જાના નુકસાનનો સમાવેશ થાય છે?","answer":"નંબર. તે માત્ર ગતિ અને ગુરુત્વાકર્ષણ સંભવિત ઊર્જાનો સરવાળો છે. \nઘર્ષણ, હવા પ્રતિકાર, પરિભ્રમણ, વિરૂપતા અને અન્ય ઉર્જા સ્થાનાંતરણનું મોડેલિંગ નથી."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-08"}});
